    { const char * tb_v424 = "// короткое дело библиотеки (память, экран, список задач): прерывания выключены и взят общий\n"; *(const char * *)tb_grow(v_lines) = tb_v424; }
    { const char * tb_v425 = "// замок — так его не делят ни прерывание, ни другое ядро процессора. Можно вкладывать\n"; *(const char * *)tb_grow(v_lines) = tb_v425; }
    { const char * tb_v426 = "TB_API volatile int tb_bkl = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v426; }
