    { const char * tb_v584 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v584; }
    { const char * tb_v585 = "// выход: QEMU с -device isa-debug-exit закрывается, без него процессор просто спит\n"; *(const char * *)tb_grow(v_lines) = tb_v585; }
    { const char * tb_v586 = "__attribute__((noreturn)) static void exit(int code) {\n"; *(const char * *)tb_grow(v_lines) = tb_v586; }
    { const char * tb_v587 = "    tb_outb(0xF4, (unsigned char)code);\n"; *(const char * *)tb_grow(v_lines) = tb_v587; }
    { const char * tb_v588 = "    for (;;) __asm__ volatile(\"cli; hlt\");\n"; *(const char * *)tb_grow(v_lines) = tb_v588; }
    { const char * tb_v589 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v589; }
    { const char * tb_v590 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v590; }
    { const char * tb_v591 = "// память: запас 64 МБ. Куски по размерам 16, 32, 64, ... байт; отданный кусок\n"; *(const char * *)tb_grow(v_lines) = tb_v591; }
    { const char * tb_v592 = "// кладётся в корзину своего размера и выдаётся снова. Последний кусок отдаётся сразу.\n"; *(const char * *)tb_grow(v_lines) = tb_v592; }
    { const char * tb_v593 = "#define TB_HEAP (64 << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v593; }
    { const char * tb_v594 = "TB_API unsigned char tb_heap[TB_HEAP] __attribute__((aligned(16), section(\".tbheap\")));\n"; *(const char * *)tb_grow(v_lines) = tb_v594; }
    { const char * tb_v595 = "TB_API size_t tb_heap_top = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v595; }
    { const char * tb_v596 = "TB_API void *tb_bins[32];\n"; *(const char * *)tb_grow(v_lines) = tb_v596; }
    { const char * tb_v597 = "// заголовок куска: размер (номер 4..31) + метка «это начало куска» — так по адресу видно,\n"; *(const char * *)tb_grow(v_lines) = tb_v597; }
    { const char * tb_v598 = "// наш ли это кусок (для передачи владения), и хозяин (клетка) рядом\n"; *(const char * *)tb_grow(v_lines) = tb_v598; }
    { const char * tb_v599 = "#define TB_HMAGIC 0x0B1A0C0000000000ull\n"; *(const char * *)tb_grow(v_lines) = tb_v599; }
    { const char * tb_v600 = "#define TB_TAG_FREE (~0ull)\n"; *(const char * *)tb_grow(v_lines) = tb_v600; }
    { const char * tb_v601 = "// запас памяти (как зона Service в старой Омниум): последние 8 МБ кучи берут только ядро,\n"; *(const char * *)tb_grow(v_lines) = tb_v601; }
    { const char * tb_v602 = "// прерывания и службы. Обычные клетки упираются раньше — и службы живут, даже когда клетки съели всё\n"; *(const char * *)tb_grow(v_lines) = tb_v602; }
    { const char * tb_v603 = "#define TB_RESERVE (8 << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v603; }
    { const char * tb_v604 = "TB_API size_t tb_heap_limit(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v604; }
    { const char * tb_v605 = "TB_API int tb_cls(size_t n) { int k = 4; while (k < 31 && ((size_t)1 << k) < n) k++; return k; }\n"; *(const char * *)tb_grow(v_lines) = tb_v605; }
    { const char * tb_v606 = "TB_API void *tb_malloc0(size_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v606; }
    { const char * tb_v607 = "    int k = tb_cls(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v607; }
    { const char * tb_v608 = "    if (tb_bins[k]) { void *p = tb_bins[k]; tb_bins[k] = *(void **)p; return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v608; }
    { const char * tb_v609 = "    size_t need = ((size_t)1 << k) + 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v609; }
    { const char * tb_v610 = "    if (tb_heap_top + need > tb_heap_limit()) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v610; }
    { const char * tb_v611 = "    unsigned char *h = tb_heap + tb_heap_top;\n"; *(const char * *)tb_grow(v_lines) = tb_v611; }
    { const char * tb_v612 = "    *(size_t *)h = (size_t)k | TB_HMAGIC;\n"; *(const char * *)tb_grow(v_lines) = tb_v612; }
    { const char * tb_v613 = "    tb_heap_top += need;\n"; *(const char * *)tb_grow(v_lines) = tb_v613; }
    { const char * tb_v614 = "    return h + 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v614; }
    { const char * tb_v615 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v615; }
    { const char * tb_v616 = "TB_API void tb_free0(void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v616; }
    { const char * tb_v617 = "    if (p == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v617; }
