    { const char * tb_v921 = "// ---------- ядро: прерывания, таймер, клавиатура, задачи, страницы памяти ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v921; }
    { const char * tb_v922 = "// on all cores здесь выполняется на одном ядре по очереди (как и было),\n"; *(const char * *)tb_grow(v_lines) = tb_v922; }
    { const char * tb_v923 = "// а background — настоящая задача: таймер переключает задачи каждые 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v923; }
    { const char * tb_v924 = "TB_API long sysconf(int n) { (void)n; return 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v924; }
    { const char * tb_v925 = "TB_API int pthread_create(pthread_t *t, void *a, void *(*run)(void *), void *arg) { (void)t; (void)a; run(arg); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v925; }
    { const char * tb_v926 = "TB_API int pthread_join(pthread_t t, void **r) { (void)t; (void)r; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v926; }
    { const char * tb_v927 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v927; }
    { const char * tb_v928 = "// адреса из раскладки ядра (компоновщик): где код, где кончается нижняя память, где куча\n"; *(const char * *)tb_grow(v_lines) = tb_v928; }
    { const char * tb_v929 = "extern char tb_code_start[], tb_code_end[], tb_tls_start[], tb_tls_end[], tb_heap_area[], tb_kernel_end[];\n"; *(const char * *)tb_grow(v_lines) = tb_v929; }
    { const char * tb_v930 = "TB_API unsigned char tb_stack[1 << 20] __attribute__((aligned(4096), used));\n"; *(const char * *)tb_grow(v_lines) = tb_v930; }
    { const char * tb_v931 = "void tb_kmain(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v931; }
    { const char * tb_v932 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v932; }
    { const char * tb_v933 = "// авария ядра: красным на экран и в порт, потом стоп\n"; *(const char * *)tb_grow(v_lines) = tb_v933; }
    { const char * tb_v934 = "__attribute__((noreturn)) static void tb_panic(const char *what, uint64_t a, uint64_t b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v934; }
    { const char * tb_v935 = "    __asm__ volatile(\"cli\");\n"; *(const char * *)tb_grow(v_lines) = tb_v935; }
    { const char * tb_v936 = "    char buf[160];\n"; *(const char * *)tb_grow(v_lines) = tb_v936; }
    { const char * tb_v937 = "    snprintf(buf, sizeof buf, \"\\n*** ядро остановлено: %s (0x%llx, 0x%llx)\\n\", what, (unsigned long long)a, (unsigned long long)b);\n"; *(const char * *)tb_grow(v_lines) = tb_v937; }
    { const char * tb_v938 = "    fputs(buf, stderr);\n"; *(const char * *)tb_grow(v_lines) = tb_v938; }
    { const char * tb_v939 = "    exit(3);\n"; *(const char * *)tb_grow(v_lines) = tb_v939; }
    { const char * tb_v940 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v940; }
    { const char * tb_v941 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v941; }
    { const char * tb_v942 = "// --- таблица сегментов x86-64: код 64 бита, данные, задача процессора (TSS, 16 байт) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v942; }
    { const char * tb_v943 = "// у каждого ядра процессора свой TSS (две записи по 8 байт): номер сегмента 0x18 + 16 × ядро\n"; *(const char * *)tb_grow(v_lines) = tb_v943; }
    { const char * tb_v944 = "TB_API uint64_t tb_gdt[3 + 2 * TB_NCPU] __attribute__((used)) = {0, 0x00AF9A000000FFFFULL, 0x00CF92000000FFFFULL};\n"; *(const char * *)tb_grow(v_lines) = tb_v944; }
    { const char * tb_v945 = "// TSS: ist[0] — отдельный стек для двойной ошибки (стек упёрся в сторожа — обработчику есть куда писать)\n"; *(const char * *)tb_grow(v_lines) = tb_v945; }
    { const char * tb_v946 = "typedef struct __attribute__((packed)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v946; }
    { const char * tb_v947 = "    uint32_t r0; uint64_t rsp[3]; uint64_t r1; uint64_t ist[7]; uint64_t r2; uint16_t r3, iomap;\n"; *(const char * *)tb_grow(v_lines) = tb_v947; }
    { const char * tb_v948 = "} tb_tss64;\n"; *(const char * *)tb_grow(v_lines) = tb_v948; }
    { const char * tb_v949 = "TB_API tb_tss64 tb_tsss[TB_NCPU] __attribute__((aligned(16)));\n"; *(const char * *)tb_grow(v_lines) = tb_v949; }
    { const char * tb_v950 = "TB_API uint64_t tb_idt[2 * 256] __attribute__((aligned(16)));\n"; *(const char * *)tb_grow(v_lines) = tb_v950; }
    { const char * tb_v951 = "TB_API struct __attribute__((packed)) { uint16_t lim; uint64_t base; } tb_gdtr, tb_idtr;\n"; *(const char * *)tb_grow(v_lines) = tb_v951; }
    { const char * tb_v952 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v952; }
    { const char * tb_v953 = "// 49 входов: 0..31 ошибки процессора, 32..47 железо (таймер, клавиатура ...), 48 — «уступить ход».\n"; *(const char * *)tb_grow(v_lines) = tb_v953; }
    { const char * tb_v954 = "// Кадр на стеке (снизу вверх): 512 байт дробей и SSE (fxsave), 15 регистров, номер, код ошибки,\n"; *(const char * *)tb_grow(v_lines) = tb_v954; }
    { const char * tb_v955 = "// и то, что положил процессор: rip, cs, rflags, rsp, ss. Задачи переключаются сменой кадра —\n"; *(const char * *)tb_grow(v_lines) = tb_v955; }
    { const char * tb_v956 = "// у каждой задачи свои регистры и свои дроби лежат в её кадре.\n"; *(const char * *)tb_grow(v_lines) = tb_v956; }
    { const char * tb_v957 = "extern char tb_isr_base[];\n"; *(const char * *)tb_grow(v_lines) = tb_v957; }
    { const char * tb_v958 = "__asm__(\".text\\n.balign 16\\n.global tb_isr_base\\ntb_isr_base:\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v958; }
    { const char * tb_v959 = "        \".set tb_v, 0\\n.rept 50\\n.balign 16\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v959; }
    { const char * tb_v960 = "        \".if (tb_v == 8) || (tb_v == 10) || (tb_v == 11) || (tb_v == 12) || (tb_v == 13) || (tb_v == 14) || (tb_v == 17) || (tb_v == 21)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v960; }
    { const char * tb_v961 = "        \".else\\npushq $0\\n.endif\\npushq $tb_v\\njmp tb_isr_common\\n.set tb_v, tb_v + 1\\n.endr\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v961; }
    { const char * tb_v962 = "        \"tb_isr_common:\\ncld\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v962; }
    { const char * tb_v963 = "        \"pushq %rax\\npushq %rcx\\npushq %rdx\\npushq %rbx\\npushq %rbp\\npushq %rsi\\npushq %rdi\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v963; }
    { const char * tb_v964 = "        \"pushq %r8\\npushq %r9\\npushq %r10\\npushq %r11\\npushq %r12\\npushq %r13\\npushq %r14\\npushq %r15\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v964; }
    { const char * tb_v965 = "        \"subq $512, %rsp\\nfxsave (%rsp)\\nmovq %rsp, %rdi\\ncall tb_isr\\nmovq %rax, %rsp\\ncall tb_switch_done\\nfxrstor (%rsp)\\naddq $512, %rsp\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v965; }
    { const char * tb_v966 = "        \"popq %r15\\npopq %r14\\npopq %r13\\npopq %r12\\npopq %r11\\npopq %r10\\npopq %r9\\npopq %r8\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v966; }
    { const char * tb_v967 = "        \"popq %rdi\\npopq %rsi\\npopq %rbp\\npopq %rbx\\npopq %rdx\\npopq %rcx\\npopq %rax\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v967; }
    { const char * tb_v968 = "        \"addq $16, %rsp\\niretq\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v968; }
    { const char * tb_v969 = "#define TB_F_VEC 79\n"; *(const char * *)tb_grow(v_lines) = tb_v969; }
    { const char * tb_v970 = "#define TB_F_ERR 80\n"; *(const char * *)tb_grow(v_lines) = tb_v970; }
    { const char * tb_v971 = "#define TB_F_RIP 81\n"; *(const char * *)tb_grow(v_lines) = tb_v971; }
    { const char * tb_v972 = "#define TB_FRAME (512 + 22 * 8)\n"; *(const char * *)tb_grow(v_lines) = tb_v972; }
    { const char * tb_v973 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v973; }
    { const char * tb_v974 = "// --- задачи: у каждой свой стек и свои «переменные потока» (temp, кэш длины) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v974; }
    { const char * tb_v975 = "#define TB_TLS_MAX 512\n"; *(const char * *)tb_grow(v_lines) = tb_v975; }
    { const char * tb_v976 = "#define TB_NTASK 32\n"; *(const char * *)tb_grow(v_lines) = tb_v976; }
    { const char * tb_v977 = "#define TB_TSTACK 65536\n"; *(const char * *)tb_grow(v_lines) = tb_v977; }
    { const char * tb_v978 = "typedef struct { pthread_t th; volatile int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v978; }
    { const char * tb_v979 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v979; }
    { const char * tb_v980 = "    uint64_t *frame; int used; volatile int done;\n"; *(const char * *)tb_grow(v_lines) = tb_v980; }
    { const char * tb_v981 = "    void *(*run)(void *); void *arg; tb_task *t;\n"; *(const char * *)tb_grow(v_lines) = tb_v981; }
    { const char * tb_v982 = "    int on;                               // на каком ядре процессора идёт сейчас (-1 — ни на каком)\n"; *(const char * *)tb_grow(v_lines) = tb_v982; }
    { const char * tb_v983 = "    int no;                               // номер клетки: по порядку запуска (1, 2, 3 ...)\n"; *(const char * *)tb_grow(v_lines) = tb_v983; }
    { const char * tb_v984 = "    uint64_t gen; long long mem;          // поколение слота (для хозяина кусков) и байты клетки\n"; *(const char * *)tb_grow(v_lines) = tb_v984; }
    { const char * tb_v985 = "    int *locks[8]; int nlocks;            // замки, которые клетка держит сейчас\n"; *(const char * *)tb_grow(v_lines) = tb_v985; }
    { const char * tb_v986 = "    int svc;                              // служба (a = service f()): ей можно в запас памяти\n"; *(const char * *)tb_grow(v_lines) = tb_v986; }
    { const char * tb_v987 = "    int soft;                             // сейчас new_mem / grow_mem: нет памяти — ошибка, а не падение\n"; *(const char * *)tb_grow(v_lines) = tb_v987; }
    { const char * tb_v988 = "    unsigned char tls[TB_TLS_MAX + 16] __attribute__((aligned(16)));   // блок переменных потока + адрес самого себя\n"; *(const char * *)tb_grow(v_lines) = tb_v988; }
    { const char * tb_v989 = "} tb_kslot;\n"; *(const char * *)tb_grow(v_lines) = tb_v989; }
    { const char * tb_v990 = "TB_API tb_kslot tb_slots[TB_NTASK];          // 0 — main\n"; *(const char * *)tb_grow(v_lines) = tb_v990; }
    { const char * tb_v991 = "TB_API unsigned char tb_tstacks[TB_NTASK][TB_TSTACK] __attribute__((aligned(4096)));\n"; *(const char * *)tb_grow(v_lines) = tb_v991; }
    { const char * tb_v992 = "TB_API int tb_nlive = 1, tb_cell_count = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v992; }
    { const char * tb_v993 = "// своё у каждой задачи (переменные потока): номер её слота; у функций прерывания tb_in_irq = 1\n"; *(const char * *)tb_grow(v_lines) = tb_v993; }
    { const char * tb_v994 = "TB_API _Thread_local int tb_cur = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v994; }
    { const char * tb_v995 = "TB_API _Thread_local int tb_in_irq = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v995; }
    { const char * tb_v996 = "TB_API unsigned char tb_fpu_init[512] __attribute__((aligned(16)));\n"; *(const char * *)tb_grow(v_lines) = tb_v996; }
    { const char * tb_v997 = "TB_API volatile uint64_t tb_ms = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v997; }
    { const char * tb_v998 = "TB_API void (*tb_irq_fn[16])(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v998; }
    { const char * tb_v999 = "TB_API uint16_t tb_pic_mask = 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v999; }
    { const char * tb_v1000 = "TB_API uint64_t tb_tls_size(void) { return (uint64_t)(tb_tls_end - tb_tls_start); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1000; }
    { const char * tb_v1001 = "// блок переменных потока: начальные значения (образ от компоновщика), в конце — адрес конца\n"; *(const char * *)tb_grow(v_lines) = tb_v1001; }
    { const char * tb_v1002 = "// (так устроено у x86-64: FS указывает на конец блока, а там лежит он сам)\n"; *(const char * *)tb_grow(v_lines) = tb_v1002; }
    { const char * tb_v1003 = "TB_API unsigned char *tb_tls_fresh(unsigned char *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1003; }
    { const char * tb_v1004 = "    uint64_t n = tb_tls_size();\n"; *(const char * *)tb_grow(v_lines) = tb_v1004; }
    { const char * tb_v1005 = "    memcpy(b, tb_tls_start, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v1005; }
    { const char * tb_v1006 = "    unsigned char *tp = b + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1006; }
    { const char * tb_v1007 = "    *(uint64_t *)tp = (uint64_t)(uintptr_t)tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v1007; }
    { const char * tb_v1008 = "    return tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v1008; }
    { const char * tb_v1009 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1009; }
    { const char * tb_v1010 = "TB_API void tb_set_fs(unsigned char *tp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1010; }
    { const char * tb_v1011 = "    uint64_t v = (uint64_t)(uintptr_t)tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v1011; }
    { const char * tb_v1012 = "    __asm__ volatile(\"wrmsr\" : : \"c\"(0xC0000100u), \"a\"((uint32_t)v), \"d\"((uint32_t)(v >> 32)) : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1012; }
    { const char * tb_v1013 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1013; }
    { const char * tb_v1014 = "TB_API unsigned char *tb_tls_tp(unsigned char *b) { return b + tb_tls_size(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1014; }
    { const char * tb_v1015 = "TB_INL void *tb_tls_self(void) { void *p; __asm__ volatile(\"movq %%fs:0, %0\" : \"=r\"(p)); return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1015; }
    { const char * tb_v1016 = "// хозяин куска: номер слота и поколение; кусок клетки, которой уже нет, никому не засчитывается\n"; *(const char * *)tb_grow(v_lines) = tb_v1016; }
    { const char * tb_v1017 = "TB_API uint64_t tb_cell_charge(size_t bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1017; }
    { const char * tb_v1018 = "    if (tb_in_irq) return 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v1018; }
    { const char * tb_v1019 = "    tb_kslot *s = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v1019; }
    { const char * tb_v1020 = "    if (tb_cur != 0 && s->mem + (long long)bytes > TB_CELL_QUOTA) return (uint64_t)-1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1020; }
    { const char * tb_v1021 = "    s->mem += (long long)bytes;\n"; *(const char * *)tb_grow(v_lines) = tb_v1021; }
    { const char * tb_v1022 = "    return (uint64_t)tb_cur | (s->gen << 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v1022; }
    { const char * tb_v1023 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1023; }
    { const char * tb_v1024 = "// new_mem / grow_mem просят память «мягко»: не хватило — ответ else err, клетка живёт\n"; *(const char * *)tb_grow(v_lines) = tb_v1024; }
    { const char * tb_v1025 = "TB_API int tb_mem_soft_now(void) { return !tb_in_irq && tb_slots[tb_cur].soft > 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1025; }
    { const char * tb_v1026 = "TB_API void tb_mem_soft(int d) { if (!tb_in_irq) tb_slots[tb_cur].soft += d; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1026; }
    { const char * tb_v1027 = "TB_API size_t tb_heap_limit(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1027; }
    { const char * tb_v1028 = "    if (tb_in_irq || tb_cur == 0 || tb_slots[tb_cur].svc) return TB_HEAP;\n"; *(const char * *)tb_grow(v_lines) = tb_v1028; }
    { const char * tb_v1029 = "    return TB_HEAP - TB_RESERVE;\n"; *(const char * *)tb_grow(v_lines) = tb_v1029; }
    { const char * tb_v1030 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1030; }
    { const char * tb_v1031 = "// хватит ли клетке квоты, если её кусок вырастет на месте (иначе растём через malloc — он и уронит)\n"; *(const char * *)tb_grow(v_lines) = tb_v1031; }
    { const char * tb_v1032 = "TB_API int tb_cell_fits(uint64_t tag, long long more) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1032; }
    { const char * tb_v1033 = "    uint64_t i = tag & 0xFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v1033; }
    { const char * tb_v1034 = "    if (i == 0 || i >= TB_NTASK || tb_slots[i].gen != (tag >> 8)) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1034; }
    { const char * tb_v1035 = "    return tb_slots[i].mem + more <= TB_CELL_QUOTA;\n"; *(const char * *)tb_grow(v_lines) = tb_v1035; }
    { const char * tb_v1036 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1036; }
    { const char * tb_v1037 = "TB_API void tb_cell_refund(uint64_t tag, long long bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1037; }
    { const char * tb_v1038 = "    uint64_t i = tag & 0xFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v1038; }
    { const char * tb_v1039 = "    if (i >= TB_NTASK || tb_slots[i].gen != (tag >> 8) || !tb_slots[i].used) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v1039; }
    { const char * tb_v1040 = "    tb_slots[i].mem -= bytes;\n"; *(const char * *)tb_grow(v_lines) = tb_v1040; }
    { const char * tb_v1041 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1041; }
    { const char * tb_v1042 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1042; }
    { const char * tb_v1043 = "TB_API void tb_pic_apply(void) { tb_outb(0x21, (unsigned char)tb_pic_mask); tb_outb(0xA1, (unsigned char)(tb_pic_mask >> 8)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1043; }
    { const char * tb_v1044 = "TB_API void tb_irq_set(int v, void (*fn)(void)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1044; }
    { const char * tb_v1045 = "    tb_irq_fn[v - 32] = fn;\n"; *(const char * *)tb_grow(v_lines) = tb_v1045; }
    { const char * tb_v1046 = "    tb_pic_mask &= (uint16_t)~(1u << (v - 32));\n"; *(const char * *)tb_grow(v_lines) = tb_v1046; }
    { const char * tb_v1047 = "    if (v >= 40) tb_pic_mask &= (uint16_t)~(1u << 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v1047; }
