    { const char * tb_v1219 = "    uint64_t low = (uint64_t)(uintptr_t)tb_heap_area;\n"; *(const char * *)tb_grow(v_lines) = tb_v1219; }
    { const char * tb_v1220 = "    uint64_t cs = (uint64_t)(uintptr_t)tb_code_start, ce = (uint64_t)(uintptr_t)tb_code_end;\n"; *(const char * *)tb_grow(v_lines) = tb_v1220; }
    { const char * tb_v1221 = "    if (low > TB_LOW_PTS * 0x200000ull) tb_panic(\"ядро слишком большое для нижних страниц\", low, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1221; }
    { const char * tb_v1222 = "    if (tb_ram_end < (uint64_t)(uintptr_t)tb_kernel_end + 0x400000u) tb_panic(\"мало памяти: запусти qemu с -m 256\", tb_ram_end, (uint64_t)(uintptr_t)tb_kernel_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v1222; }
