    { const char * tb_v1241 = "        if (a >= tb_ram_end) tb_pdir[3][(a >> 21) & 511] = a | 0x83 | 0x18;\n"; *(const char * *)tb_grow(v_lines) = tb_v1241; }
    { const char * tb_v1242 = "    // CR0.WP: и ядро не может писать в страницы «только читать»\n"; *(const char * *)tb_grow(v_lines) = tb_v1242; }
    { const char * tb_v1243 = "    __asm__ volatile(\"movq %0, %%cr3\\nmovq %%cr0, %%rax\\norq $0x10000, %%rax\\nmovq %%rax, %%cr0\\n\" : : \"r\"(tb_pml4) : \"rax\", \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1243; }
    { const char * tb_v1244 = "    tb_pg_next = (uint64_t)(uintptr_t)tb_kernel_end;\n"; *(const char * *)tb_grow(v_lines) = tb_v1244; }
