    { const char * tb_v1298 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1298; }
    { const char * tb_v1299 = "// кусок переходит текущей клетке (взяла из канала)\n"; *(const char * *)tb_grow(v_lines) = tb_v1299; }
    { const char * tb_v1300 = "TB_API void tb_adopt(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1300; }
