    { const char * tb_v2131 = "    void *free; long long nfree, bump;   // bump: блоки с этого номера ещё ни разу не брали (там нули)\n"; *(const char * *)tb_grow(v_lines) = tb_v2131; }
    { const char * tb_v2132 = "    struct tb_gpage *next, *prev, *anext;\n"; *(const char * *)tb_grow(v_lines) = tb_v2132; }
    { const char * tb_v2133 = "} tb_gpage;\n"; *(const char * *)tb_grow(v_lines) = tb_v2133; }
