    { const char * tb_v2136 = "TB_API tb_gpage *tb_gall = 0, *tb_glarge = 0, *tb_gavail[2][TB_GNC];\n"; *(const char * *)tb_grow(v_lines) = tb_v2136; }
    { const char * tb_v2137 = "// адрес → страница: таблица в два шага (биты 47..32, потом 31..16)\n"; *(const char * *)tb_grow(v_lines) = tb_v2137; }
    { const char * tb_v2138 = "TB_API tb_gpage **tb_gdir[1 << 16];\n"; *(const char * *)tb_grow(v_lines) = tb_v2138; }
    { const char * tb_v2139 = "TB_API uintptr_t tb_glo = ~(uintptr_t)0, tb_ghi = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2139; }
    { const char * tb_v2140 = "TB_API long long tb_gsince = 0, tb_glive = 0, tb_gnext = 8LL << 20, tb_gstress = 0, tb_gcount = 0, tb_gruns = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2140; }
    { const char * tb_v2141 = "TB_API int tb_gready = 0, tb_goff = 0, tb_gstats = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2141; }
    { const char * tb_v2142 = "TB_API char *tb_gtop = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2142; }
    { const char * tb_v2143 = "TB_API pthread_mutex_t tb_glock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2143; }
    { const char * tb_v2144 = "TB_API tb_grange *tb_groots = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2144; }
    { const char * tb_v2145 = "TB_API long long tb_gnroots = 0, tb_gcaproots = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2145; }
    { const char * tb_v2146 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2146; }
    { const char * tb_v2147 = "TB_API void tb_gsetup(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2147; }
    { const char * tb_v2148 = "    int c = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2148; }
