    { const char * tb_v2152 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2152; }
    { const char * tb_v2153 = "    tb_gready = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2153; }
    { const char * tb_v2154 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2154; }
    { const char * tb_v2155 = "TB_INL tb_gpage *tb_gmap_get(uintptr_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2155; }
    { const char * tb_v2156 = "    if (a >> 48) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2156; }
    { const char * tb_v2157 = "    tb_gpage **l2 = tb_gdir[a >> 32];\n"; *(const char * *)tb_grow(v_lines) = tb_v2157; }
    { const char * tb_v2158 = "    return l2 ? l2[(a >> TB_GSH) & 0xFFFF] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2158; }
    { const char * tb_v2159 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2159; }
    { const char * tb_v2160 = "TB_API void tb_gmap_put(uintptr_t a, tb_gpage *pg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2160; }
    { const char * tb_v2161 = "    tb_gpage ***d = &tb_gdir[a >> 32];\n"; *(const char * *)tb_grow(v_lines) = tb_v2161; }
    { const char * tb_v2162 = "    if (!*d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2162; }
    { const char * tb_v2163 = "        *d = calloc(1 << 16, sizeof(tb_gpage *));\n"; *(const char * *)tb_grow(v_lines) = tb_v2163; }
    { const char * tb_v2164 = "        if (!*d) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2164; }
    { const char * tb_v2165 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2165; }
    { const char * tb_v2166 = "    (*d)[(a >> TB_GSH) & 0xFFFF] = pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v2166; }
    { const char * tb_v2167 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2167; }
    { const char * tb_v2168 = "TB_API void tb_gmap_add(tb_gpage *pg, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2168; }
    { const char * tb_v2169 = "    for (long long o = 0; o < size; o += TB_GPG) tb_gmap_put((uintptr_t)pg->start + o, pg);\n"; *(const char * *)tb_grow(v_lines) = tb_v2169; }
    { const char * tb_v2170 = "    if ((uintptr_t)pg->start < tb_glo) tb_glo = (uintptr_t)pg->start;\n"; *(const char * *)tb_grow(v_lines) = tb_v2170; }
    { const char * tb_v2171 = "    if ((uintptr_t)pg->start + size > tb_ghi) tb_ghi = (uintptr_t)pg->start + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v2171; }
    { const char * tb_v2172 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2172; }
    { const char * tb_v2173 = "TB_API void tb_gmap_remove(tb_gpage *pg, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2173; }
    { const char * tb_v2174 = "    for (long long o = 0; o < size; o += TB_GPG) tb_gmap_put((uintptr_t)pg->start + o, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2174; }
    { const char * tb_v2175 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2175; }
    { const char * tb_v2176 = "// память у системы: mmap всегда отдаёт нули и выровнено по 64 КБ (лишнее по краям отдаём назад)\n"; *(const char * *)tb_grow(v_lines) = tb_v2176; }
    { const char * tb_v2177 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v2177; }
