    { const char * tb_v3539 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3539; }
    { const char * tb_v3540 = "// элемент списка заранее (prefetch за пределами списка ничего не ломает)\n"; *(const char * *)tb_grow(v_lines) = tb_v3540; }
    { const char * tb_v3541 = "TB_INL void tb_lpre(tb_list *l, long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3541; }
