    { const char * tb_v3544 = "// ---------- холодные качества obj: своя память, отдельно от горячих ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3544; }
    { const char * tb_v3545 = "TB_API void *tb_cold_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3545; }
    { const char * tb_v3546 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3546; }
