    { const char * tb_v3773 = "    if (n && tb_mem_check) fprintf(stderr, \"TB_MEM_CHECK: не освобождено блоков %lld (%lld байт), первый из new_mem в строке %d\\n\", n, bytes, first);\n"; *(const char * *)tb_grow(v_lines) = tb_v3773; }
