    { const char * tb_v3776 = "static void tb_mem_touch(uintptr_t a, uint64_t n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3776; }
    { const char * tb_v3777 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3777; }
