    { const char * tb_v3838 = "// проверить адрес для free_mem / grow_mem; вернуть заголовок блока\n"; *(const char * *)tb_grow(v_lines) = tb_v3838; }
    { const char * tb_v3839 = "static tb_memh *tb_mem_own(long long a, int line, const char *who) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3839; }
    { const char * tb_v3840 = "    char buf[120];\n"; *(const char * *)tb_grow(v_lines) = tb_v3840; }
    { const char * tb_v3841 = "    if (tb_memchk()) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3841; }
