    { const char * tb_v3909 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3909; }
    { const char * tb_v3910 = "// ---------- use c: функции из C ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3910; }
    { const char * tb_v3911 = "// настоящее имя функции C (на Mac у имён в библиотеке спереди _)\n"; *(const char * *)tb_grow(v_lines) = tb_v3911; }
    { const char * tb_v3912 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v3912; }
    { const char * tb_v3913 = "#define TB_CSYM(s) __asm__(\"_\" s)\n"; *(const char * *)tb_grow(v_lines) = tb_v3913; }
    { const char * tb_v3914 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3914; }
