    { const char * tb_v3916 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3916; }
    { const char * tb_v3917 = "// текст из C: копия в память Tachbit (C может потом поменять или отдать свой); NULL → \"\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3917; }
    { const char * tb_v3918 = "TB_API const char *tb_ctext(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3918; }
    { const char * tb_v3919 = "    if (!p) return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3919; }
