    { const char * tb_v4425 = "// короткий щелчок (касание тачпада): нажали и отпустили между двумя кадрами — mouse_down() всё равно разок скажет «да»\n"; *(const char * *)tb_grow(v_lines) = tb_v4425; }
    { const char * tb_v4426 = "TB_API int tb_mtap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4426; }
    { const char * tb_v4427 = "// колёсико: шагов с прошлого mouse_wheel() (+ вперёд, от себя; − назад); у тачпада шаги дробные — копим\n"; *(const char * *)tb_grow(v_lines) = tb_v4427; }
    { const char * tb_v4428 = "TB_API int tb_wheel = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4428; }
    { const char * tb_v4429 = "// боковые кнопки мыши: [0] назад, [1] вперёд; tap — нажали и отпустили между кадрами\n"; *(const char * *)tb_grow(v_lines) = tb_v4429; }
    { const char * tb_v4430 = "TB_API int tb_mside[2], tb_mside_tap[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v4430; }
    { const char * tb_v4431 = "TB_API void tb_side(int b, int down) { tb_mside[b] = down; if (down) tb_mside_tap[b] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4431; }
    { const char * tb_v4432 = "TB_API double tb_wheel_f = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4432; }
    { const char * tb_v4433 = "TB_API void tb_wheel_add(double d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4433; }
    { const char * tb_v4434 = "    tb_wheel_f += d;\n"; *(const char * *)tb_grow(v_lines) = tb_v4434; }
    { const char * tb_v4435 = "    int n = (int)tb_wheel_f;\n"; *(const char * *)tb_grow(v_lines) = tb_v4435; }
    { const char * tb_v4436 = "    tb_wheel += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4436; }
    { const char * tb_v4437 = "    tb_wheel_f -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4437; }
    { const char * tb_v4438 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4438; }
    { const char * tb_v4439 = "// буквы, набранные с прошлого typed_text(), в UTF-8 (стрелки, Enter и прочие не буквы не попадают)\n"; *(const char * *)tb_grow(v_lines) = tb_v4439; }
    { const char * tb_v4440 = "TB_API char tb_typed[512];\n"; *(const char * *)tb_grow(v_lines) = tb_v4440; }
    { const char * tb_v4441 = "TB_API int tb_ntyped = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4441; }
    { const char * tb_v4442 = "TB_API char *tb_gfx_clip_get(void);          // свои у каждой системы: текст (malloc) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v4442; }
    { const char * tb_v4443 = "TB_API void tb_gfx_clip_set(const char *s);\n"; *(const char * *)tb_grow(v_lines) = tb_v4443; }
    { const char * tb_v4444 = "TB_API void tb_gfx_cursor(int k);              // 0 стрелка, 1 рука, 2 текст, 3 двигать, 4 ↔, 5 ↕, 6 ждать, 7 спрятать\n"; *(const char * *)tb_grow(v_lines) = tb_v4444; }
    { const char * tb_v4445 = "TB_API int tb_cursor_want = 0;                 // курсор, который просили до window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v4445; }
    { const char * tb_v4446 = "TB_API void tb_type_cp(unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4446; }
    { const char * tb_v4447 = "    if (u < 32 || u == 127 || (u >= 0xF700 && u <= 0xF8FF) || u > 0x10FFFF) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4447; }
    { const char * tb_v4448 = "    if (tb_ntyped + 4 >= (int)sizeof tb_typed) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4448; }
    { const char * tb_v4449 = "    char *o = tb_typed + tb_ntyped;\n"; *(const char * *)tb_grow(v_lines) = tb_v4449; }
    { const char * tb_v4450 = "    if (u < 0x80) { o[0] = (char)u; tb_ntyped += 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4450; }
    { const char * tb_v4451 = "    else if (u < 0x800) { o[0] = (char)(0xC0 | (u >> 6)); o[1] = (char)(0x80 | (u & 63)); tb_ntyped += 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4451; }
    { const char * tb_v4452 = "    else if (u < 0x10000) { o[0] = (char)(0xE0 | (u >> 12)); o[1] = (char)(0x80 | ((u >> 6) & 63)); o[2] = (char)(0x80 | (u & 63)); tb_ntyped += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4452; }
    { const char * tb_v4453 = "    else { o[0] = (char)(0xF0 | (u >> 18)); o[1] = (char)(0x80 | ((u >> 12) & 63)); o[2] = (char)(0x80 | ((u >> 6) & 63)); o[3] = (char)(0x80 | (u & 63)); tb_ntyped += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4453; }
    { const char * tb_v4454 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4454; }
    { const char * tb_v4455 = "TB_API void tb_type_utf8(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4455; }
    { const char * tb_v4456 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4456; }
    { const char * tb_v4457 = "    while (p && *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4457; }
    { const char * tb_v4458 = "        unsigned u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4458; }
    { const char * tb_v4459 = "        if (u >= 0x80) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4459; }
    { const char * tb_v4460 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4460; }
    { const char * tb_v4461 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v4461; }
    { const char * tb_v4462 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v4462; }
    { const char * tb_v4463 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4463; }
    { const char * tb_v4464 = "        tb_type_cp(u);\n"; *(const char * *)tb_grow(v_lines) = tb_v4464; }
    { const char * tb_v4465 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4465; }
    { const char * tb_v4466 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4466; }
    { const char * tb_v4467 = "TB_API unsigned char tb_keys[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v4467; }
    { const char * tb_v4468 = "TB_API unsigned char tb_ktap[256];   // клавишу нажали и отпустили между кадрами: key_down() разок скажет «да»\n"; *(const char * *)tb_grow(v_lines) = tb_v4468; }
    { const char * tb_v4469 = "TB_API long long tb_last_frame = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4469; }
    { const char * tb_v4470 = "// клавиши: буквы и цифры — свой код ASCII (A..Z, 0..9), остальные:\n"; *(const char * *)tb_grow(v_lines) = tb_v4470; }
    { const char * tb_v4471 = "enum { TB_K_ENTER = 10, TB_K_ESC = 27, TB_K_SPACE = 32, TB_K_BACK = 8, TB_K_TAB = 9,\n"; *(const char * *)tb_grow(v_lines) = tb_v4471; }
    { const char * tb_v4472 = "       TB_K_UP = 17, TB_K_DOWN = 18, TB_K_RIGHT = 19, TB_K_LEFT = 20, TB_K_SHIFT = 21,\n"; *(const char * *)tb_grow(v_lines) = tb_v4472; }
    { const char * tb_v4473 = "       TB_K_CMD = 1, TB_K_CTRL = 2, TB_K_ALT = 3, TB_K_DEL = 4, TB_K_HOME = 5, TB_K_END = 6, TB_K_PGUP = 7,\n"; *(const char * *)tb_grow(v_lines) = tb_v4473; }
    { const char * tb_v4474 = "       TB_K_PGDN = 11, TB_K_F1 = 128 };   // F1..F12 — 128..139\n"; *(const char * *)tb_grow(v_lines) = tb_v4474; }
    { const char * tb_v4475 = "// ---------- картинки PNG (load_image; JPEG, BMP, GIF — ниже) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4475; }
    { const char * tb_v4476 = "// Свой маленький разбор PNG: распаковка deflate (как zlib) и фильтры строк.\n"; *(const char * *)tb_grow(v_lines) = tb_v4476; }
    { const char * tb_v4477 = "// Картинка хранится точками 0xAARRGGBB; точка видна, если её прозрачность (A) не меньше 128.\n"; *(const char * *)tb_grow(v_lines) = tb_v4477; }
    { const char * tb_v4478 = "typedef struct { const unsigned char *p, *end; unsigned bits; int nb, err; unsigned char *out; size_t n, cap; } tb_zs;\n"; *(const char * *)tb_grow(v_lines) = tb_v4478; }
    { const char * tb_v4479 = "typedef struct { short count[16], sym[320]; } tb_huff;\n"; *(const char * *)tb_grow(v_lines) = tb_v4479; }
    { const char * tb_v4480 = "TB_API unsigned tb_zbits(tb_zs *z, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4480; }
    { const char * tb_v4481 = "    while (z->nb < n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4481; }
    { const char * tb_v4482 = "        if (z->p >= z->end) { z->err = 1; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4482; }
    { const char * tb_v4483 = "        z->bits |= (unsigned)*z->p++ << z->nb; z->nb += 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v4483; }
    { const char * tb_v4484 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4484; }
    { const char * tb_v4485 = "    unsigned v = z->bits & ((1u << n) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4485; }
    { const char * tb_v4486 = "    z->bits >>= n; z->nb -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4486; }
    { const char * tb_v4487 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v4487; }
    { const char * tb_v4488 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4488; }
    { const char * tb_v4489 = "TB_API void tb_zput(tb_zs *z, unsigned char b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4489; }
    { const char * tb_v4490 = "    if (z->n == z->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4490; }
    { const char * tb_v4491 = "        size_t nc = z->cap ? z->cap * 2 : 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v4491; }
    { const char * tb_v4492 = "        unsigned char *q = realloc(z->out, nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v4492; }
    { const char * tb_v4493 = "        if (!q) { z->err = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4493; }
    { const char * tb_v4494 = "        z->out = q; z->cap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v4494; }
    { const char * tb_v4495 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4495; }
    { const char * tb_v4496 = "    z->out[z->n++] = b;\n"; *(const char * *)tb_grow(v_lines) = tb_v4496; }
    { const char * tb_v4497 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4497; }
    { const char * tb_v4498 = "TB_API void tb_hbuild(tb_huff *h, const unsigned char *len, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4498; }
    { const char * tb_v4499 = "    short offs[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v4499; }
    { const char * tb_v4500 = "    memset(h->count, 0, sizeof h->count);\n"; *(const char * *)tb_grow(v_lines) = tb_v4500; }
    { const char * tb_v4501 = "    for (int i = 0; i < n; i++) h->count[len[i]]++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4501; }
    { const char * tb_v4502 = "    h->count[0] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4502; }
    { const char * tb_v4503 = "    offs[1] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4503; }
    { const char * tb_v4504 = "    for (int l = 1; l < 15; l++) offs[l + 1] = offs[l] + h->count[l];\n"; *(const char * *)tb_grow(v_lines) = tb_v4504; }
    { const char * tb_v4505 = "    for (int i = 0; i < n; i++) if (len[i]) h->sym[offs[len[i]]++] = (short)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v4505; }
    { const char * tb_v4506 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4506; }
    { const char * tb_v4507 = "TB_API int tb_hdec(tb_zs *z, const tb_huff *h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4507; }
    { const char * tb_v4508 = "    int code = 0, first = 0, index = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4508; }
    { const char * tb_v4509 = "    for (int l = 1; l < 16; l++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4509; }
    { const char * tb_v4510 = "        code |= (int)tb_zbits(z, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4510; }
    { const char * tb_v4511 = "        int c = h->count[l];\n"; *(const char * *)tb_grow(v_lines) = tb_v4511; }
    { const char * tb_v4512 = "        if (code - c < first) return h->sym[index + (code - first)];\n"; *(const char * *)tb_grow(v_lines) = tb_v4512; }
    { const char * tb_v4513 = "        index += c; first += c; first <<= 1; code <<= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4513; }
    { const char * tb_v4514 = "        if (z->err) return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4514; }
    { const char * tb_v4515 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4515; }
    { const char * tb_v4516 = "    z->err = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4516; }
    { const char * tb_v4517 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4517; }
