    { const char * tb_v5287 = "        if (u < s) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5287; }
    { const char * tb_v5288 = "        unsigned delta = tb_u16(f, deltas + 2 * i), ro = tb_u16(f, ranges + 2 * i);\n"; *(const char * *)tb_grow(v_lines) = tb_v5288; }
    { const char * tb_v5289 = "        if (ro == 0) return (u + delta) & 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v5289; }
    { const char * tb_v5290 = "        unsigned g = tb_u16(f, ranges + 2 * i + ro + 2 * (u - s));\n"; *(const char * *)tb_grow(v_lines) = tb_v5290; }
    { const char * tb_v5291 = "        return g ? (g + delta) & 0xFFFF : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5291; }
    { const char * tb_v5292 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5292; }
    { const char * tb_v5293 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5293; }
    { const char * tb_v5294 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5294; }
    { const char * tb_v5295 = "static double tb_ttf_adv(const tb_font_t *f, unsigned g) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5295; }
    { const char * tb_v5296 = "    unsigned i = (int)g < f->nhm ? g : (unsigned)f->nhm - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5296; }
    { const char * tb_v5297 = "    return tb_u16(f, f->hmtx + 4 * (size_t)i);\n"; *(const char * *)tb_grow(v_lines) = tb_v5297; }
    { const char * tb_v5298 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5298; }
    { const char * tb_v5299 = "static size_t tb_ttf_gpos(const tb_font_t *f, unsigned g, size_t *len) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5299; }
    { const char * tb_v5300 = "    if ((int)g >= f->nglyphs) { *len = 0; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5300; }
    { const char * tb_v5301 = "    size_t a, b;\n"; *(const char * *)tb_grow(v_lines) = tb_v5301; }
    { const char * tb_v5302 = "    if (f->locfmt == 0) { a = 2 * (size_t)tb_u16(f, f->loca + 2 * g); b = 2 * (size_t)tb_u16(f, f->loca + 2 * g + 2); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5302; }
    { const char * tb_v5303 = "    else { a = tb_u32(f, f->loca + 4 * g); b = tb_u32(f, f->loca + 4 * g + 4); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5303; }
    { const char * tb_v5304 = "    *len = b > a ? b - a : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5304; }
    { const char * tb_v5305 = "    return f->glyf + a;\n"; *(const char * *)tb_grow(v_lines) = tb_v5305; }
    { const char * tb_v5306 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5306; }
    { const char * tb_v5307 = "// контур буквы → отрезки (в точках экрана, y вниз); m — матрица шрифт → экран: x' = m0 x + m2 y + m4, y' = m1 x + m3 y + m5\n"; *(const char * *)tb_grow(v_lines) = tb_v5307; }
    { const char * tb_v5308 = "typedef struct { float *e; int n, cap; } tb_edges;\n"; *(const char * *)tb_grow(v_lines) = tb_v5308; }
    { const char * tb_v5309 = "static void tb_edge(tb_edges *E, double x0, double y0, double x1, double y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5309; }
    { const char * tb_v5310 = "    if (y0 == y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5310; }
    { const char * tb_v5311 = "    if (E->n == E->cap) { E->cap = E->cap ? E->cap * 2 : 256; E->e = realloc(E->e, (size_t)E->cap * 4 * sizeof(float)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5311; }
    { const char * tb_v5312 = "    float *p = E->e + 4 * E->n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5312; }
    { const char * tb_v5313 = "    p[0] = (float)x0; p[1] = (float)y0; p[2] = (float)x1; p[3] = (float)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5313; }
    { const char * tb_v5314 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5314; }
    { const char * tb_v5315 = "static void tb_quad(tb_edges *E, double x0, double y0, double cx, double cy, double x1, double y1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5315; }
    { const char * tb_v5316 = "    double dx = x0 - 2 * cx + x1, dy = y0 - 2 * cy + y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5316; }
    { const char * tb_v5317 = "    int n = 1 + (int)sqrt(sqrt(dx * dx + dy * dy) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5317; }
    { const char * tb_v5318 = "    if (n > 16) n = 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v5318; }
    { const char * tb_v5319 = "    double px = x0, py = y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5319; }
    { const char * tb_v5320 = "    for (int i = 1; i <= n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5320; }
    { const char * tb_v5321 = "        double t = (double)i / n, u = 1 - t;\n"; *(const char * *)tb_grow(v_lines) = tb_v5321; }
    { const char * tb_v5322 = "        double qx = u * u * x0 + 2 * u * t * cx + t * t * x1, qy = u * u * y0 + 2 * u * t * cy + t * t * y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5322; }
    { const char * tb_v5323 = "        tb_edge(E, px, py, qx, qy);\n"; *(const char * *)tb_grow(v_lines) = tb_v5323; }
    { const char * tb_v5324 = "        px = qx; py = qy;\n"; *(const char * *)tb_grow(v_lines) = tb_v5324; }
    { const char * tb_v5325 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5325; }
    { const char * tb_v5326 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5326; }
    { const char * tb_v5327 = "static void tb_ttf_outline(const tb_font_t *f, unsigned g, const double *m, tb_edges *E, int depth) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5327; }
    { const char * tb_v5328 = "    size_t len, o = tb_ttf_gpos(f, g, &len);\n"; *(const char * *)tb_grow(v_lines) = tb_v5328; }
    { const char * tb_v5329 = "    if (len < 10 || depth > 8) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5329; }
    { const char * tb_v5330 = "    int nc = tb_s16(f, o);\n"; *(const char * *)tb_grow(v_lines) = tb_v5330; }
    { const char * tb_v5331 = "    if (nc < 0) {   // составная буква (ё = е + точки): части со своим сдвигом и масштабом\n"; *(const char * *)tb_grow(v_lines) = tb_v5331; }
    { const char * tb_v5332 = "        size_t p = o + 10;\n"; *(const char * *)tb_grow(v_lines) = tb_v5332; }
    { const char * tb_v5333 = "        for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5333; }
    { const char * tb_v5334 = "            unsigned fl = tb_u16(f, p), sub = tb_u16(f, p + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v5334; }
    { const char * tb_v5335 = "            p += 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v5335; }
    { const char * tb_v5336 = "            double dx = 0, dy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5336; }
    { const char * tb_v5337 = "            if (fl & 1) { if (fl & 2) { dx = tb_s16(f, p); dy = tb_s16(f, p + 2); } p += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5337; }
    { const char * tb_v5338 = "            else { if (fl & 2) { dx = (int8_t)f->d[p]; dy = (int8_t)f->d[p + 1]; } p += 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5338; }
    { const char * tb_v5339 = "            double a = 1, b = 0, c = 0, dd = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5339; }
    { const char * tb_v5340 = "            if (fl & 8) { a = dd = tb_s16(f, p) / 16384.0; p += 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5340; }
