    { const char * tb_v5483 = "    if (len < 10) return c;   // пробел: рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v5483; }
    { const char * tb_v5484 = "    double s = (double)size / f->upem;\n"; *(const char * *)tb_grow(v_lines) = tb_v5484; }
    { const char * tb_v5485 = "    int left = (int)floor(tb_s16(f, o + 2) * s) - 1, right = (int)ceil(tb_s16(f, o + 6) * s) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5485; }
    { const char * tb_v5486 = "    int top = (int)floor(-tb_s16(f, o + 8) * s) - 1, bottom = (int)ceil(-tb_s16(f, o + 4) * s) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5486; }
    { const char * tb_v5487 = "    int w = right - left, h = bottom - top;\n"; *(const char * *)tb_grow(v_lines) = tb_v5487; }
