    { const char * tb_v5494 = "    free(E.e);\n"; *(const char * *)tb_grow(v_lines) = tb_v5494; }
    { const char * tb_v5495 = "    size_t need = tb_imgpx_n + (size_t)w * h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5495; }
