    { const char * tb_v5497 = "    tb_image *list = realloc(tb_imgs, (size_t)(tb_nimg + 1) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v5497; }
    { const char * tb_v5498 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v5498; }
    { const char * tb_v5499 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v5499; }
    { const char * tb_v5500 = "    if (!all || !list) { free(acc); return c; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5500; }
    { const char * tb_v5501 = "    uint32_t *px = tb_imgpx + tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5501; }
    { const char * tb_v5502 = "    for (int j = 0; j < h; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5502; }
