    { const char * tb_v5518 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5518; }
    { const char * tb_v5519 = "// высота строки — size * 5 / 4; линия букв — так, чтобы верх и низ шрифта легли в эту строку\n"; *(const char * *)tb_grow(v_lines) = tb_v5519; }
    { const char * tb_v5520 = "static int tb_font_base(const tb_font_t *f, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5520; }
    { const char * tb_v5521 = "    double lh = size * 5 / 4.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5521; }
    { const char * tb_v5522 = "    return (int)floor(lh * f->asc / (f->asc - f->desc) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v5522; }
    { const char * tb_v5523 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5523; }
    { const char * tb_v5524 = "static unsigned tb_utf8_next(const unsigned char **pp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5524; }
    { const char * tb_v5525 = "    const unsigned char *p = *pp;\n"; *(const char * *)tb_grow(v_lines) = tb_v5525; }
    { const char * tb_v5526 = "    unsigned u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5526; }
    { const char * tb_v5527 = "    if (u >= 0x80) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5527; }
    { const char * tb_v5528 = "        int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5528; }
    { const char * tb_v5529 = "        u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v5529; }
    { const char * tb_v5530 = "        while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v5530; }
    { const char * tb_v5531 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5531; }
    { const char * tb_v5532 = "    *pp = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v5532; }
    { const char * tb_v5533 = "    return u;\n"; *(const char * *)tb_grow(v_lines) = tb_v5533; }
    { const char * tb_v5534 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5534; }
    { const char * tb_v5535 = "TB_API long long tb_text_width(long long fi, const char *s, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5535; }
    { const char * tb_v5536 = "    if (fi < 0 || fi >= tb_nfonts || size <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5536; }
    { const char * tb_v5537 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v5537; }
    { const char * tb_v5538 = "    double scale = (double)size / f->upem, pen = 0, best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5538; }
    { const char * tb_v5539 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v5539; }
    { const char * tb_v5540 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5540; }
    { const char * tb_v5541 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v5541; }
    { const char * tb_v5542 = "        if (u == '\\n') { if (pen > best) best = pen; pen = 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5542; }
    { const char * tb_v5543 = "        pen += tb_ttf_adv(f, tb_ttf_glyph(f, u)) * scale;\n"; *(const char * *)tb_grow(v_lines) = tb_v5543; }
    { const char * tb_v5544 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5544; }
    { const char * tb_v5545 = "    if (pen > best) best = pen;\n"; *(const char * *)tb_grow(v_lines) = tb_v5545; }
    { const char * tb_v5546 = "    return (long long)floor(best + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v5546; }
    { const char * tb_v5547 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5547; }
    { const char * tb_v5548 = "TB_API void tb_draw_image_a(long long id, long long x, long long y);\n"; *(const char * *)tb_grow(v_lines) = tb_v5548; }
    { const char * tb_v5549 = "TB_API void tb_draw_font(long long fi, long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5549; }
    { const char * tb_v5550 = "    if (!tb_px || fi < 0 || fi >= tb_nfonts || size <= 0 || size > 1000) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5550; }
    { const char * tb_v5551 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v5551; }
    { const char * tb_v5552 = "    double scale = (double)size / f->upem, pen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5552; }
    { const char * tb_v5553 = "    long long base = y + tb_font_base(f, size), lh = size * 5 / 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v5553; }
    { const char * tb_v5554 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v5554; }
    { const char * tb_v5555 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5555; }
    { const char * tb_v5556 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v5556; }
    { const char * tb_v5557 = "        if (u == '\\n') { pen = 0; base += lh; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5557; }
    { const char * tb_v5558 = "        unsigned g = tb_ttf_glyph(f, u);\n"; *(const char * *)tb_grow(v_lines) = tb_v5558; }
    { const char * tb_v5559 = "        long long gx = x + (long long)floor(pen + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v5559; }
