    { const char * tb_v5561 = "        if (u == ' ' || gx >= tb_gw || base - 2 * size > tb_gh) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v5561; }
    { const char * tb_v5562 = "        tb_gcache *gc = tb_glyph_img((int)fi, g, (int)size, (uint32_t)c & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v5562; }
    { const char * tb_v5563 = "        if (gc->img >= 0) tb_draw_image_a(gc->img, gx + gc->left, base + gc->top);\n"; *(const char * *)tb_grow(v_lines) = tb_v5563; }
    { const char * tb_v5564 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5564; }
    { const char * tb_v5565 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5565; }
    { const char * tb_v5566 = "// ---------- рисование на видеокарте (GPU) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v5566; }
    { const char * tb_v5567 = "// Кадр не рисуется точками на процессоре: каждая фигура записывается как «экземпляр»\n"; *(const char * *)tb_grow(v_lines) = tb_v5567; }
    { const char * tb_v5568 = "// (прямоугольник, круг или буква), а видеокарта рисует их все разом — по тем же правилам\n"; *(const char * *)tb_grow(v_lines) = tb_v5568; }
    { const char * tb_v5569 = "// точек, что и процессор (tb_draw_* ниже). Mac — Metal, Linux и Windows — Vulkan.\n"; *(const char * *)tb_grow(v_lines) = tb_v5569; }
    { const char * tb_v5570 = "// Если видеокарты нет (нет драйвера Vulkan, нет экрана) — рисуем как раньше, на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v5570; }
    { const char * tb_v5571 = "//   TB_GPU=0        — всегда на процессоре\n"; *(const char * *)tb_grow(v_lines) = tb_v5571; }
    { const char * tb_v5572 = "//   TB_GPU_CHECK=1  — рисовать и там и там и сверять каждый кадр точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v5572; }
    { const char * tb_v5573 = "//   TB_GPU_INFO=1   — сказать, чем рисуем\n"; *(const char * *)tb_grow(v_lines) = tb_v5573; }
    { const char * tb_v5574 = "typedef struct { int32_t x0, y0, x1, y1, ox, oy; uint32_t c, m; } tb_ginst;   // 32 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v5574; }
    { const char * tb_v5575 = "enum { TB_GI_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5575; }
    { const char * tb_v5576 = "TB_API int tb_gpu_on = 0, tb_gpu_check = 0, tb_gpu_first = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5576; }
    { const char * tb_v5577 = "TB_API tb_ginst *tb_gi = 0;            // память экземпляров (видна видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v5577; }
    { const char * tb_v5578 = "TB_API int tb_gin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5578; }
    { const char * tb_v5579 = "// 3D: глубина. У треугольника сетки своя «плоскость глубины» A, B, C (целые числа, см. tb_tri3_depth);\n"; *(const char * *)tb_grow(v_lines) = tb_v5579; }
    { const char * tb_v5580 = "// она лежит в tb_gplane[набор * TB_GI_CAP + номер фигуры], а в m — 2 | (это место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v5580; }
    { const char * tb_v5581 = "typedef struct { uint32_t a, b, c, pad; } tb_gplane_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v5581; }
    { const char * tb_v5582 = "TB_API tb_gplane_t *tb_gplane = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5582; }
    { const char * tb_v5583 = "TB_API int tb_gzclr = 1;               // видеокарта: в начале кадра стереть глубину\n"; *(const char * *)tb_grow(v_lines) = tb_v5583; }
    { const char * tb_v5584 = "TB_API int tb_zclr = 1;                // процессор: то же для tb_zb\n"; *(const char * *)tb_grow(v_lines) = tb_v5584; }
    { const char * tb_v5585 = "TB_API uint32_t *tb_zb = 0;            // процессор: глубина каждой точки\n"; *(const char * *)tb_grow(v_lines) = tb_v5585; }
    { const char * tb_v5586 = "TB_API long long tb_zb_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5586; }
    { const char * tb_v5587 = "// 3D на видеокарте: сетка один раз ложится в память видеокарты (tb_mesh_pack), а на каждый draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v5587; }
    { const char * tb_v5588 = "// пишется только запись: 3 строки по 4 целых — поворот (камера × поворот сетки) × 2^30 и сдвиг × 4096.\n"; *(const char * *)tb_grow(v_lines) = tb_v5588; }
    { const char * tb_v5589 = "// В пачке фигур это одна особая фигура m = 3: x0 — сетка, y0 — какие грани не видны, x1 — первая запись,\n"; *(const char * *)tb_grow(v_lines) = tb_v5589; }
    { const char * tb_v5590 = "// y1 — сколько записей подряд. Углы, экран и глубину считает видеокарта (tb3.vert) целыми числами —\n"; *(const char * *)tb_grow(v_lines) = tb_v5590; }
    { const char * tb_v5591 = "// той же формулой, что процессор (tb_m3_corner): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v5591; }
    { const char * tb_v5592 = "typedef struct { int32_t r[12]; } tb_grec;\n"; *(const char * *)tb_grow(v_lines) = tb_v5592; }
    { const char * tb_v5593 = "enum { TB_GR_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5593; }
    { const char * tb_v5594 = "TB_API tb_grec *tb_grec_p = 0;         // записи всех наборов подряд (видны видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v5594; }
    { const char * tb_v5595 = "TB_API int tb_grn = 0;                 // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v5595; }
    { const char * tb_v5596 = "TB_API int tb_gpu_mesh = 0;            // 1: видеокарта умеет считать сетки сама (конвейер собрался)\n"; *(const char * *)tb_grow(v_lines) = tb_v5596; }
    { const char * tb_v5597 = "TB_API int tb_mesh_gdirty = 1;         // сетки поменялись: перед рисованием залить заново\n"; *(const char * *)tb_grow(v_lines) = tb_v5597; }
    { const char * tb_v5598 = "TB_API long long tb_gbatch = 1;        // номер текущей пачки (растёт после каждой отдачи видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v5598; }
    { const char * tb_v5599 = "typedef struct { float size[2]; int32_t tbase, ntri, rbase, f, gw, gh, cull; } tb_gpc;   // постоянные шейдера сеток\n"; *(const char * *)tb_grow(v_lines) = tb_v5599; }
    { const char * tb_v5600 = "TB_API long long tb_mesh_pack(int32_t *dst);   // все сетки подряд для видеокарты (dst = 0: только размер)\n"; *(const char * *)tb_grow(v_lines) = tb_v5600; }
    { const char * tb_v5601 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc);   // постоянные для фигуры m = 3\n"; *(const char * *)tb_grow(v_lines) = tb_v5601; }
    { const char * tb_v5602 = "// TB_GSLOTS наборов памяти по кругу: пока видеокарта рисует один кадр, программа уже пишет следующий\n"; *(const char * *)tb_grow(v_lines) = tb_v5602; }
    { const char * tb_v5603 = "enum { TB_GSLOTS = 3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5603; }
    { const char * tb_v5604 = "TB_API int tb_gslot = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5604; }
    { const char * tb_v5605 = "TB_API uint32_t *tb_gpu_back = 0;      // TB_GPU_CHECK: кадр, прочитанный обратно с видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v5605; }
    { const char * tb_v5606 = "TB_API long long tb_gpu_frames = 0, tb_gpu_bad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5606; }
    { const char * tb_v5607 = "TB_API void tb_gpu_flush(int present);   // своя у каждой системы: Metal или Vulkan\n"; *(const char * *)tb_grow(v_lines) = tb_v5607; }
    { const char * tb_v5608 = "TB_API void tb_gpu_vsync(void);          // включить или выключить ожидание экрана (tb_gpu_nosync)\n"; *(const char * *)tb_grow(v_lines) = tb_v5608; }
    { const char * tb_v5609 = "TB_API int tb_gpu_nosync = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5609; }
    { const char * tb_v5610 = "TB_API int tb_gpu_resize(int ow, int oh);   // окно поменяло размер\n"; *(const char * *)tb_grow(v_lines) = tb_v5610; }
    { const char * tb_v5611 = "// окно можно тянуть мышью, если программа спросила его размер (window_w, window_h)\n"; *(const char * *)tb_grow(v_lines) = tb_v5611; }
    { const char * tb_v5612 = "TB_API int tb_resizable = 0, tb_new_w = 0, tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5612; }
