    { const char * tb_v7618 = "    static const char *names[7] = { \"arrowCursor\", \"pointingHandCursor\", \"IBeamCursor\", \"openHandCursor\", \"resizeLeftRightCursor\", \"resizeUpDownCursor\", \"arrowCursor\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v7618; }
