    { const char * tb_v7631 = "// ---------- Metal (Mac) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7631; }
    { const char * tb_v7632 = "// Metal зовём так же, как Cocoa: через objc_msgSend. Шейдер (tb_msl выше, compiler/gpu/tb.metal)\n"; *(const char * *)tb_grow(v_lines) = tb_v7632; }
    { const char * tb_v7633 = "// Mac переводит сам при запуске. Сама библиотека Metal грузится через dlopen: нет её — процессор.\n"; *(const char * *)tb_grow(v_lines) = tb_v7633; }
