    { const char * tb_v7639 = "    psom, mbuf, grbuf; } tb_mtl;   // psom — сетки на видеокарте (tb_vert3), mbuf — сетки, grbuf — записи draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v7639; }
    { const char * tb_v7640 = "// дождаться всех кадров, которые видеокарта ещё рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v7640; }
    { const char * tb_v7641 = "TB_API void tb_mtl_idle(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7641; }
    { const char * tb_v7642 = "    for (int s = 0; s < TB_GSLOTS; s++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7642; }
    { const char * tb_v7643 = "        if (tb_mtl.cbs[s]) { TB_MSG(void, tb_mtl.cbs[s], \"waitUntilCompleted\"); TB_MSG(void, tb_mtl.cbs[s], \"release\"); tb_mtl.cbs[s] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7643; }
