    { const char * tb_v7655 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7655; }
    { const char * tb_v7656 = "// сетки поменялись (mesh_add): все сетки — в новый буфер видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v7656; }
    { const char * tb_v7657 = "TB_API int tb_mtl_meshes(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7657; }
