    { const char * tb_v8296 = "    Atom utf8 = XInternAtom(tb_dpy, \"UTF8_STRING\", False), targets = XInternAtom(tb_dpy, \"TARGETS\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v8296; }
