    { const char * tb_v8367 = "        if (e.type == SelectionRequest) tb_x_clip_answer(&e.xselectionrequest);\n"; *(const char * *)tb_grow(v_lines) = tb_v8367; }
    { const char * tb_v8368 = "        else if (e.type == ClientMessage && (Atom)e.xclient.data.l[0] == tb_wm_del) tb_gclosed = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8368; }
