    { const char * tb_v8371 = "            if (k) { tb_keys[k] = e.type == KeyPress; if (tb_keys[k]) tb_ktap[k] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8371; }
    { const char * tb_v8372 = "            if (e.type == KeyPress) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8372; }
    { const char * tb_v8373 = "                char buf[16]; KeySym ks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8373; }
