    { const char * tb_v8377 = "        } else if (e.type == ButtonPress || e.type == ButtonRelease) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8377; }
    { const char * tb_v8378 = "            if (e.xbutton.button == 1) { tb_mdown = e.type == ButtonPress; if (tb_mdown) tb_mtap = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8378; }
    { const char * tb_v8379 = "            if (e.xbutton.button == 8 || e.xbutton.button == 9) tb_side(e.xbutton.button - 8, e.type == ButtonPress);\n"; *(const char * *)tb_grow(v_lines) = tb_v8379; }
    { const char * tb_v8380 = "            if (e.type == ButtonPress && e.xbutton.button == 4) tb_wheel_add(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8380; }
