    { const char * tb_v8551 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8551; }
    { const char * tb_v8552 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8552; }
