    { const char * tb_v8566 = "// скругление углов: \"\" или \"all\" — все; иначе слова top bottom left right tl tr bl br через пробел\n"; *(const char * *)tb_grow(v_lines) = tb_v8566; }
    { const char * tb_v8567 = "TB_API int tb_corners(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8567; }
    { const char * tb_v8568 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v8568; }
    { const char * tb_v8569 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8569; }
    { const char * tb_v8570 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v8570; }
    { const char * tb_v8571 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8571; }
