    { const char * tb_v8592 = "        tb_gpu_circle(x + r, y + h - 1 - r, r, c); tb_gpu_circle(x + w - 1 - r, y + h - 1 - r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8592; }
    { const char * tb_v8593 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8593; }
