    { const char * tb_v8603 = "        long long a = x + (lc ? r : 0), b = x + w - (rc ? r : 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8603; }
    { const char * tb_v8604 = "        if (a < 0) a = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8604; }
    { const char * tb_v8605 = "        if (b > tb_gw) b = tb_gw;\n"; *(const char * *)tb_grow(v_lines) = tb_v8605; }
    { const char * tb_v8606 = "        if ((cc >> 24) & 255) { for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], cc); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8606; }
    { const char * tb_v8607 = "        else for (long long i = a; i < b; i++) tb_px[j * tb_gw + i] = cc & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v8607; }
    { const char * tb_v8608 = "        // углы: покрытие точки по расстоянию до центра угла\n"; *(const char * *)tb_grow(v_lines) = tb_v8608; }
    { const char * tb_v8609 = "        for (int side = 0; side < 2; side++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8609; }
    { const char * tb_v8610 = "            if (!(side ? rc : lc)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v8610; }
