    { const char * tb_v8633 = "                // строка (или столбец) — во временный ряд, потом скользящая сумма окна 2r+1\n"; *(const char * *)tb_grow(v_lines) = tb_v8633; }
    { const char * tb_v8634 = "                for (long long k = 0; k < len; k++) line[k] = dir ? tb_px[(y0 + k) * tb_gw + x0 + o] : tb_px[(y0 + o) * tb_gw + x0 + k];\n"; *(const char * *)tb_grow(v_lines) = tb_v8634; }
    { const char * tb_v8635 = "                long long sr = 0, sg = 0, sb = 0, win = 2 * r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8635; }
    { const char * tb_v8636 = "                for (long long k = -r; k <= r; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8636; }
