    { const char * tb_v8638 = "                    sr += (v >> 16) & 255; sg += (v >> 8) & 255; sb += v & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v8638; }
    { const char * tb_v8639 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v8639; }
    { const char * tb_v8640 = "                for (long long k = 0; k < len; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8640; }
    { const char * tb_v8641 = "                    uint32_t v = (uint32_t)((sr / win) << 16 | (sg / win) << 8 | (sb / win));\n"; *(const char * *)tb_grow(v_lines) = tb_v8641; }
    { const char * tb_v8642 = "                    if (dir) tb_px[(y0 + k) * tb_gw + x0 + o] = v; else tb_px[(y0 + o) * tb_gw + x0 + k] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v8642; }
    { const char * tb_v8643 = "                    uint32_t out = line[k - r < 0 ? 0 : k - r], in = line[k + r + 1 >= len ? len - 1 : k + r + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v8643; }
    { const char * tb_v8644 = "                    sr += (long long)((in >> 16) & 255) - ((out >> 16) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v8644; }
