    { const char * tb_v8698 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v8698; }
    { const char * tb_v8699 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8699; }
    { const char * tb_v8700 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v8700; }
    { const char * tb_v8701 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8701; }
    { const char * tb_v8702 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8702; }
    { const char * tb_v8703 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v8703; }
    { const char * tb_v8704 = "    return e > 0 || (e == 0 && (ey > 0 || (ey == 0 && ex < 0)));\n"; *(const char * *)tb_grow(v_lines) = tb_v8704; }
    { const char * tb_v8705 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8705; }
    { const char * tb_v8706 = "// глубина точки (x, y) по плоскости треугольника — так же, как в шейдере: 32-битные числа\n"; *(const char * *)tb_grow(v_lines) = tb_v8706; }
    { const char * tb_v8707 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v8707; }
    { const char * tb_v8708 = "TB_INL uint32_t tb_tri3_depth(const uint32_t *pl, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8708; }
    { const char * tb_v8709 = "    uint32_t k = pl[2] + pl[0] * (uint32_t)(2 * x + 1) + pl[1] * (uint32_t)(2 * y + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8709; }
    { const char * tb_v8710 = "    int32_t d = (int32_t)k >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v8710; }
