    { const char * tb_v8712 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8712; }
    { const char * tb_v8713 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v8713; }
    { const char * tb_v8714 = "// gpu, cpu — где рисовать (сетку на видеокарте может считать сама видеокарта: тогда здесь только процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v8714; }
    { const char * tb_v8715 = "static void tb_tri_draw_x(long long *t, long long c, const uint32_t *pl, int gpu, int cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8715; }
    { const char * tb_v8716 = "    if (!tb_tri_prep(t)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8716; }
    { const char * tb_v8717 = "    if (gpu) { if (pl) tb_gpu_tri3(t, c, pl); else tb_gpu_triangle(t, c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8717; }
    { const char * tb_v8718 = "    if (cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8718; }
    { const char * tb_v8719 = "        long long xa = t[0], xb = t[0], ya = t[1], yb = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v8719; }
    { const char * tb_v8720 = "        for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8720; }
    { const char * tb_v8721 = "            if (t[i] < xa) xa = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8721; }
    { const char * tb_v8722 = "            if (t[i] > xb) xb = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8722; }
    { const char * tb_v8723 = "            if (t[i + 1] < ya) ya = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v8723; }
    { const char * tb_v8724 = "            if (t[i + 1] > yb) yb = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v8724; }
    { const char * tb_v8725 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8725; }
    { const char * tb_v8726 = "        if (xa < 0) xa = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8726; }
    { const char * tb_v8727 = "        if (ya < 0) ya = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8727; }
