    { const char * tb_v8832 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8832; }
    { const char * tb_v8833 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8833; }
