    { const char * tb_v8865 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v8865; }
    { const char * tb_v8866 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v8866; }
    { const char * tb_v8867 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v8867; }
    { const char * tb_v8868 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v8868; }
    { const char * tb_v8869 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v8869; }
    { const char * tb_v8870 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v8870; }
    { const char * tb_v8871 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v8871; }
    { const char * tb_v8872 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v8872; }
    { const char * tb_v8873 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v8873; }
    { const char * tb_v8874 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v8874; }
    { const char * tb_v8875 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v8875; }
    { const char * tb_v8876 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v8876; }
    { const char * tb_v8877 = "typedef struct { double *v; long long nv, capv; uint32_t *t, *c; long long n, cap; long long *hk; long long hcap;\n"; *(const char * *)tb_grow(v_lines) = tb_v8877; }
    { const char * tb_v8878 = "    int32_t *vi; double bb[6]; int big, cull, cullok; long long gv, gt, gused;\n"; *(const char * *)tb_grow(v_lines) = tb_v8878; }
    { const char * tb_v8879 = "    long long nch, *chr; double *chs, bs[4]; int chok; } tb_mesh;   // куски: chr — (первый треугольник, сколько), chs и bs — шары (центр, радиус)\n"; *(const char * *)tb_grow(v_lines) = tb_v8879; }
    { const char * tb_v8880 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8880; }
    { const char * tb_v8881 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8881; }
    { const char * tb_v8882 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v8882; }
    { const char * tb_v8883 = "TB_API double tb_camf[3] = { 0, 0, 1 };                      // вперёд\n"; *(const char * *)tb_grow(v_lines) = tb_v8883; }
    { const char * tb_v8884 = "TB_API long long tb_mesh_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8884; }
    { const char * tb_v8885 = "    if (tb_nmesh == tb_capmesh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8885; }
    { const char * tb_v8886 = "        tb_capmesh = tb_capmesh ? tb_capmesh * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v8886; }
    { const char * tb_v8887 = "        tb_meshes = (tb_mesh *)realloc(tb_meshes, sizeof(tb_mesh) * tb_capmesh);\n"; *(const char * *)tb_grow(v_lines) = tb_v8887; }
    { const char * tb_v8888 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8888; }
    { const char * tb_v8889 = "    memset(&tb_meshes[tb_nmesh], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v8889; }
    { const char * tb_v8890 = "    tb_meshes[tb_nmesh].gused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8890; }
    { const char * tb_v8891 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8891; }
    { const char * tb_v8892 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8892; }
    { const char * tb_v8893 = "TB_INL uint64_t tb_vhash(const double *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8893; }
    { const char * tb_v8894 = "    uint64_t h = 1469598103934665603ULL, w[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v8894; }
    { const char * tb_v8895 = "    memcpy(w, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v8895; }
    { const char * tb_v8896 = "    for (int i = 0; i < 3; i++) { h ^= w[i]; h *= 1099511628211ULL; h ^= h >> 29; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8896; }
    { const char * tb_v8897 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8897; }
    { const char * tb_v8898 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8898; }
    { const char * tb_v8899 = "// номер угла (x, y, z) в сетке: такой же уже есть — тот же номер (таблица с открытой адресацией)\n"; *(const char * *)tb_grow(v_lines) = tb_v8899; }
    { const char * tb_v8900 = "static uint32_t tb_mesh_vertex(tb_mesh *m, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8900; }
    { const char * tb_v8901 = "    double p[3] = { x + 0.0, y + 0.0, z + 0.0 };   // + 0.0: -0 и 0 — один угол\n"; *(const char * *)tb_grow(v_lines) = tb_v8901; }
    { const char * tb_v8902 = "    if (m->nv * 2 >= m->hcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8902; }
    { const char * tb_v8903 = "        long long nc = m->hcap ? m->hcap * 2 : 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v8903; }
    { const char * tb_v8904 = "        long long *nk = (long long *)malloc(sizeof(long long) * nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v8904; }
    { const char * tb_v8905 = "        for (long long i = 0; i < nc; i++) nk[i] = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8905; }
    { const char * tb_v8906 = "        for (long long v = 0; v < m->nv; v++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8906; }
    { const char * tb_v8907 = "            uint64_t h = tb_vhash(m->v + 3 * v) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8907; }
    { const char * tb_v8908 = "            while (nk[h] >= 0) h = (h + 1) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8908; }
    { const char * tb_v8909 = "            nk[h] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v8909; }
    { const char * tb_v8910 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8910; }
    { const char * tb_v8911 = "        free(m->hk); m->hk = nk; m->hcap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v8911; }
    { const char * tb_v8912 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8912; }
    { const char * tb_v8913 = "    uint64_t h = tb_vhash(p) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8913; }
    { const char * tb_v8914 = "    while (m->hk[h] >= 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8914; }
    { const char * tb_v8915 = "        if (memcmp(m->v + 3 * m->hk[h], p, 24) == 0) return (uint32_t)m->hk[h];\n"; *(const char * *)tb_grow(v_lines) = tb_v8915; }
    { const char * tb_v8916 = "        h = (h + 1) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8916; }
    { const char * tb_v8917 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8917; }
    { const char * tb_v8918 = "    if (m->nv == m->capv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8918; }
    { const char * tb_v8919 = "        m->capv = m->capv ? m->capv * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v8919; }
    { const char * tb_v8920 = "        m->v = (double *)realloc(m->v, sizeof(double) * 3 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v8920; }
    { const char * tb_v8921 = "        m->vi = (int32_t *)realloc(m->vi, sizeof(int32_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v8921; }
    { const char * tb_v8922 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8922; }
    { const char * tb_v8923 = "    memcpy(m->v + 3 * m->nv, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v8923; }
    { const char * tb_v8924 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8924; }
    { const char * tb_v8925 = "        if (m->nv == 0 || p[i] < m->bb[i]) m->bb[i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8925; }
    { const char * tb_v8926 = "        if (m->nv == 0 || p[i] > m->bb[3 + i]) m->bb[3 + i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8926; }
    { const char * tb_v8927 = "        if (!(fabs(p[i]) < 262144)) m->big = 1;   // и NaN тоже\n"; *(const char * *)tb_grow(v_lines) = tb_v8927; }
    { const char * tb_v8928 = "        m->vi[4 * m->nv + i] = m->big ? 0 : (int32_t)tb_rnd(p[i] * 4096);\n"; *(const char * *)tb_grow(v_lines) = tb_v8928; }
    { const char * tb_v8929 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8929; }
    { const char * tb_v8930 = "    m->vi[4 * m->nv + 3] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8930; }
    { const char * tb_v8931 = "    m->hk[h] = m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v8931; }
    { const char * tb_v8932 = "    return (uint32_t)m->nv++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8932; }
    { const char * tb_v8933 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8933; }
    { const char * tb_v8934 = "TB_API void tb_mesh_add(long long id, double x1, double y1, double z1, double x2, double y2, double z2,\n"; *(const char * *)tb_grow(v_lines) = tb_v8934; }
    { const char * tb_v8935 = "                        double x3, double y3, double z3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8935; }
    { const char * tb_v8936 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8936; }
    { const char * tb_v8937 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v8937; }
    { const char * tb_v8938 = "    // видеокарта ещё не нарисовала эту сетку из текущей пачки: сначала отдать пачку (там старая сетка)\n"; *(const char * *)tb_grow(v_lines) = tb_v8938; }
    { const char * tb_v8939 = "    if (tb_gpu_on && m->gused == tb_gbatch) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8939; }
    { const char * tb_v8940 = "    tb_mesh_gdirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8940; }
    { const char * tb_v8941 = "    m->cullok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8941; }
    { const char * tb_v8942 = "    m->chok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8942; }
    { const char * tb_v8943 = "    if (m->n == m->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8943; }
    { const char * tb_v8944 = "        m->cap = m->cap ? m->cap * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v8944; }
    { const char * tb_v8945 = "        m->t = (uint32_t *)realloc(m->t, sizeof(uint32_t) * 3 * m->cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v8945; }
    { const char * tb_v8946 = "        m->c = (uint32_t *)realloc(m->c, sizeof(uint32_t) * m->cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v8946; }
    { const char * tb_v8947 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8947; }
    { const char * tb_v8948 = "    uint32_t *t = m->t + 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8948; }
    { const char * tb_v8949 = "    t[0] = tb_mesh_vertex(m, x1, y1, z1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8949; }
    { const char * tb_v8950 = "    t[1] = tb_mesh_vertex(m, x2, y2, z2);\n"; *(const char * *)tb_grow(v_lines) = tb_v8950; }
    { const char * tb_v8951 = "    t[2] = tb_mesh_vertex(m, x3, y3, z3);\n"; *(const char * *)tb_grow(v_lines) = tb_v8951; }
    { const char * tb_v8952 = "    m->c[m->n++] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v8952; }
    { const char * tb_v8953 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8953; }
    { const char * tb_v8954 = "TB_API void tb_camera(double x, double y, double z, double lx, double ly, double lz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8954; }
    { const char * tb_v8955 = "    double f[3] = { lx - x, ly - y, lz - z }, l = sqrt(f[0] * f[0] + f[1] * f[1] + f[2] * f[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v8955; }
    { const char * tb_v8956 = "    if (l < 1e-12) return;   // смотреть в себя нельзя: камера не меняется\n"; *(const char * *)tb_grow(v_lines) = tb_v8956; }
    { const char * tb_v8957 = "    for (int i = 0; i < 3; i++) f[i] /= l;\n"; *(const char * *)tb_grow(v_lines) = tb_v8957; }
    { const char * tb_v8958 = "    double up[3] = { 0, 1, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8958; }
    { const char * tb_v8959 = "    if (fabs(f[1]) > 0.9999) { up[1] = 0; up[2] = 1; }   // смотрим прямо вверх или вниз\n"; *(const char * *)tb_grow(v_lines) = tb_v8959; }
    { const char * tb_v8960 = "    double r[3] = { up[1] * f[2] - up[2] * f[1], up[2] * f[0] - up[0] * f[2], up[0] * f[1] - up[1] * f[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v8960; }
    { const char * tb_v8961 = "    l = sqrt(r[0] * r[0] + r[1] * r[1] + r[2] * r[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v8961; }
    { const char * tb_v8962 = "    for (int i = 0; i < 3; i++) r[i] /= l;\n"; *(const char * *)tb_grow(v_lines) = tb_v8962; }
    { const char * tb_v8963 = "    double u[3] = { f[1] * r[2] - f[2] * r[1], f[2] * r[0] - f[0] * r[2], f[0] * r[1] - f[1] * r[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v8963; }
    { const char * tb_v8964 = "    tb_cam[0] = x; tb_cam[1] = y; tb_cam[2] = z;\n"; *(const char * *)tb_grow(v_lines) = tb_v8964; }
    { const char * tb_v8965 = "    for (int i = 0; i < 3; i++) { tb_cam[3 + i] = r[i]; tb_cam[6 + i] = u[i]; tb_camf[i] = f[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8965; }
    { const char * tb_v8966 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8966; }
    { const char * tb_v8967 = "// плоскость глубины по трём точкам экрана (x, y, D); 0 — треугольник ребром к нам, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v8967; }
    { const char * tb_v8968 = "TB_INL int tb_tri3_plane(const double *sx, const double *sy, const double *dd, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8968; }
    { const char * tb_v8969 = "    double e1x = sx[1] - sx[0], e1y = sy[1] - sy[0], e2x = sx[2] - sx[0], e2y = sy[2] - sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v8969; }
    { const char * tb_v8970 = "    double area = e1x * e2y - e1y * e2x;\n"; *(const char * *)tb_grow(v_lines) = tb_v8970; }
    { const char * tb_v8971 = "    if (fabs(area) < 0.5) return 0;   // смотрит на нас ребром: точек почти нет\n"; *(const char * *)tb_grow(v_lines) = tb_v8971; }
    { const char * tb_v8972 = "    double ia = 1 / area;\n"; *(const char * *)tb_grow(v_lines) = tb_v8972; }
    { const char * tb_v8973 = "    double ax = ((dd[1] - dd[0]) * e2y - (dd[2] - dd[0]) * e1y) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v8973; }
    { const char * tb_v8974 = "    double by = ((dd[2] - dd[0]) * e1x - (dd[1] - dd[0]) * e2x) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v8974; }
    { const char * tb_v8975 = "    if (ax > 1e9) ax = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v8975; }
    { const char * tb_v8976 = "    if (ax < -1e9) ax = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v8976; }
    { const char * tb_v8977 = "    if (by > 1e9) by = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v8977; }
    { const char * tb_v8978 = "    if (by < -1e9) by = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v8978; }
    { const char * tb_v8979 = "    double c0 = dd[0] - ax * sx[0] - by * sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v8979; }
    { const char * tb_v8980 = "    // в целые: точка берётся по центру (2x + 1) / 2, поэтому ax / 2; ещё × 64 для точности\n"; *(const char * *)tb_grow(v_lines) = tb_v8980; }
    { const char * tb_v8981 = "    pl[0] = (uint32_t)tb_rnd(ax * 32); pl[1] = (uint32_t)tb_rnd(by * 32); pl[2] = (uint32_t)tb_rnd(c0 * 64);\n"; *(const char * *)tb_grow(v_lines) = tb_v8981; }
    { const char * tb_v8982 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8982; }
    { const char * tb_v8983 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8983; }
    { const char * tb_v8984 = "// углы сетки после камеры: место перед камерой и на экране (округлённое), глубина D\n"; *(const char * *)tb_grow(v_lines) = tb_v8984; }
    { const char * tb_v8985 = "typedef struct { double cx, cy, cz, sx, sy, dd; long long rx, ry; int front, near_ok; } tb_3v;\n"; *(const char * *)tb_grow(v_lines) = tb_v8985; }
    { const char * tb_v8986 = "TB_API tb_3v *tb_3vs = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8986; }
    { const char * tb_v8987 = "TB_API long long tb_3vcap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8987; }
    { const char * tb_v8988 = "// старый путь (дроби): сетка задевает камеру или край, где целые не годятся — обрезка у камеры и рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v8988; }
    { const char * tb_v8989 = "TB_API long long *tb_3vst = 0, tb_3vgen = 0;   // какой угол уже посчитан в этом вызове\n"; *(const char * *)tb_grow(v_lines) = tb_v8989; }
    { const char * tb_v8990 = "static void tb_draw_mesh_d(tb_mesh *m, double x, double y, double z, double turn, long long t0, long long t1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8990; }
