    { const char * tb_v9086 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = b[2] - a[2], d2 = c[2] - a[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9086; }
    { const char * tb_v9087 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v9087; }
    { const char * tb_v9088 = "    long long C = 64 * a[2] - 2 * A * a[0] - 2 * B * a[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v9088; }
