    { const char * tb_v9093 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v9093; }
    { const char * tb_v9094 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v9094; }
    { const char * tb_v9095 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v9095; }
    { const char * tb_v9096 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9096; }
    { const char * tb_v9097 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v9097; }
    { const char * tb_v9098 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v9098; }
    { const char * tb_v9099 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9099; }
    { const char * tb_v9100 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9100; }
    { const char * tb_v9101 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v9101; }
    { const char * tb_v9102 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9102; }
    { const char * tb_v9103 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9103; }
    { const char * tb_v9104 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v9104; }
    { const char * tb_v9105 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9105; }
