    { const char * tb_v9165 = "typedef struct { tb_mesh *m; long long id; int cull; long long ri, rbatch; tb_grec rec; } tb_m3_go;\n"; *(const char * *)tb_grow(v_lines) = tb_v9165; }
    { const char * tb_v9166 = "TB_API long long *tb_3ist = 0, tb_3igen = 0;   // какой угол уже посчитан в этом вызове (процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v9166; }
    { const char * tb_v9167 = "static void tb_m3_draw(tb_m3_go *go, long long t0, long long tn) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9167; }
    { const char * tb_v9168 = "    tb_mesh *m = go->m;\n"; *(const char * *)tb_grow(v_lines) = tb_v9168; }
