    { const char * tb_v9201 = "// куски сетки: треугольники делятся пополам по самой длинной стороне, пока в куске не больше 256.\n"; *(const char * *)tb_grow(v_lines) = tb_v9201; }
    { const char * tb_v9202 = "// Треугольники переставляются так, чтобы каждый кусок шёл подряд; у каждого куска свой шар\n"; *(const char * *)tb_grow(v_lines) = tb_v9202; }
    { const char * tb_v9203 = "static int tb_kd_ax;\n"; *(const char * *)tb_grow(v_lines) = tb_v9203; }
    { const char * tb_v9204 = "static const float *tb_kd_c;\n"; *(const char * *)tb_grow(v_lines) = tb_v9204; }
    { const char * tb_v9205 = "static int tb_kd_cmp(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9205; }
    { const char * tb_v9206 = "    float x = tb_kd_c[3 * *(const uint32_t *)a + tb_kd_ax], y = tb_kd_c[3 * *(const uint32_t *)b + tb_kd_ax];\n"; *(const char * *)tb_grow(v_lines) = tb_v9206; }
    { const char * tb_v9207 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v9207; }
    { const char * tb_v9208 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9208; }
    { const char * tb_v9209 = "static void tb_kd(tb_mesh *m, uint32_t *ix, long long n, const float *cen, long long *at) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9209; }
    { const char * tb_v9210 = "    if (n <= 256) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9210; }
    { const char * tb_v9211 = "        long long c = m->nch++;\n"; *(const char * *)tb_grow(v_lines) = tb_v9211; }
    { const char * tb_v9212 = "        m->chr[2 * c] = *at; m->chr[2 * c + 1] = n; *at += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9212; }
    { const char * tb_v9213 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v9213; }
    { const char * tb_v9214 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9214; }
    { const char * tb_v9215 = "    float lo[3] = { 1e30f, 1e30f, 1e30f }, hi[3] = { -1e30f, -1e30f, -1e30f };\n"; *(const char * *)tb_grow(v_lines) = tb_v9215; }
    { const char * tb_v9216 = "    for (long long i = 0; i < n; i++) for (int k = 0; k < 3; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9216; }
    { const char * tb_v9217 = "        float v = cen[3 * ix[i] + k];\n"; *(const char * *)tb_grow(v_lines) = tb_v9217; }
    { const char * tb_v9218 = "        if (v < lo[k]) lo[k] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v9218; }
    { const char * tb_v9219 = "        if (v > hi[k]) hi[k] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v9219; }
    { const char * tb_v9220 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9220; }
    { const char * tb_v9221 = "    int ax = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9221; }
    { const char * tb_v9222 = "    for (int k = 1; k < 3; k++) if (hi[k] - lo[k] > hi[ax] - lo[ax]) ax = k;\n"; *(const char * *)tb_grow(v_lines) = tb_v9222; }
