    { const char * tb_v9229 = "    double lo[3] = { 1e300, 1e300, 1e300 }, hi[3] = { -1e300, -1e300, -1e300 }, r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9229; }
    { const char * tb_v9230 = "    for (long long t = t0; t < t0 + tn; t++) for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9230; }
    { const char * tb_v9231 = "        const double *p = m->v + 3 * m->t[3 * t + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v9231; }
    { const char * tb_v9232 = "        for (int k = 0; k < 3; k++) { if (p[k] < lo[k]) lo[k] = p[k]; if (p[k] > hi[k]) hi[k] = p[k]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9232; }
