    { const char * tb_v9364 = "// ---------- звук: load_sound, play_sound, play_sound_at, listener ... ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v9364; }
    { const char * tb_v9365 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v9365; }
    { const char * tb_v9366 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v9366; }
    { const char * tb_v9367 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v9367; }
    { const char * tb_v9368 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v9368; }
    { const char * tb_v9369 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v9369; }
    { const char * tb_v9370 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v9370; }
    { const char * tb_v9371 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v9371; }
    { const char * tb_v9372 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v9372; }
    { const char * tb_v9373 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v9373; }
    { const char * tb_v9374 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v9374; }
