    { const char * tb_v9386 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v9386; }
    { const char * tb_v9387 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v9387; }
    { const char * tb_v9388 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v9388; }
