    { const char * tb_v9391 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v9391; }
    { const char * tb_v9392 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v9392; }
    { const char * tb_v9393 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9393; }
    { const char * tb_v9394 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9394; }
    { const char * tb_v9395 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v9395; }
    { const char * tb_v9396 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v9396; }
    { const char * tb_v9397 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9397; }
    { const char * tb_v9398 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9398; }
    { const char * tb_v9399 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9399; }
    { const char * tb_v9400 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9400; }
    { const char * tb_v9401 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9401; }
    { const char * tb_v9402 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9402; }
    { const char * tb_v9403 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v9403; }
    { const char * tb_v9404 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9404; }
    { const char * tb_v9405 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v9405; }
    { const char * tb_v9406 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9406; }
    { const char * tb_v9407 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v9407; }
    { const char * tb_v9408 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v9408; }
    { const char * tb_v9409 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v9409; }
    { const char * tb_v9410 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v9410; }
    { const char * tb_v9411 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v9411; }
    { const char * tb_v9412 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v9412; }
    { const char * tb_v9413 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9413; }
    { const char * tb_v9414 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9414; }
    { const char * tb_v9415 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v9415; }
    { const char * tb_v9416 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v9416; }
    { const char * tb_v9417 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9417; }
    { const char * tb_v9418 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v9418; }
    { const char * tb_v9419 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9419; }
    { const char * tb_v9420 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9420; }
    { const char * tb_v9421 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v9421; }
    { const char * tb_v9422 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9422; }
    { const char * tb_v9423 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9423; }
    { const char * tb_v9424 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v9424; }
    { const char * tb_v9425 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9425; }
    { const char * tb_v9426 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v9426; }
    { const char * tb_v9427 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v9427; }
    { const char * tb_v9428 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9428; }
    { const char * tb_v9429 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9429; }
    { const char * tb_v9430 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v9430; }
    { const char * tb_v9431 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v9431; }
    { const char * tb_v9432 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9432; }
    { const char * tb_v9433 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v9433; }
    { const char * tb_v9434 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v9434; }
    { const char * tb_v9435 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v9435; }
    { const char * tb_v9436 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v9436; }
    { const char * tb_v9437 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v9437; }
    { const char * tb_v9438 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v9438; }
    { const char * tb_v9439 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9439; }
    { const char * tb_v9440 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9440; }
    { const char * tb_v9441 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v9441; }
    { const char * tb_v9442 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v9442; }
    { const char * tb_v9443 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v9443; }
    { const char * tb_v9444 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v9444; }
    { const char * tb_v9445 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v9445; }
    { const char * tb_v9446 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v9446; }
    { const char * tb_v9447 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v9447; }
    { const char * tb_v9448 = "    double want = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9448; }
    { const char * tb_v9449 = "    if (!v->fresh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9449; }
    { const char * tb_v9450 = "        double sp = (d - v->lastd) * TB_SR / TB_SBLOCK;\n"; *(const char * *)tb_grow(v_lines) = tb_v9450; }
    { const char * tb_v9451 = "        if (fabs(sp) < 686) want = 343 / (343 + sp);   // быстрее — это прыжок, не движение\n"; *(const char * *)tb_grow(v_lines) = tb_v9451; }
    { const char * tb_v9452 = "        if (want < 0.5) want = 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v9452; }
    { const char * tb_v9453 = "        if (want > 2) want = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9453; }
    { const char * tb_v9454 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9454; }
    { const char * tb_v9455 = "    v->dop = v->fresh ? 1 : v->dop * 0.8 + want * 0.2;\n"; *(const char * *)tb_grow(v_lines) = tb_v9455; }
    { const char * tb_v9456 = "    v->lastd = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v9456; }
    { const char * tb_v9457 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9457; }
    { const char * tb_v9458 = "// смешать n кадров всех голосов в out (стерео, по очереди лево-право)\n"; *(const char * *)tb_grow(v_lines) = tb_v9458; }
    { const char * tb_v9459 = "static void tb_mix(float *out, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9459; }
    { const char * tb_v9460 = "    memset(out, 0, sizeof(float) * 2 * (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v9460; }
    { const char * tb_v9461 = "    pthread_mutex_lock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v9461; }
    { const char * tb_v9462 = "    for (int k = 0; k < TB_NVOICE; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9462; }
    { const char * tb_v9463 = "        tb_voice *v = &tb_voices[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v9463; }
    { const char * tb_v9464 = "        if (!v->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v9464; }
    { const char * tb_v9465 = "        tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v9465; }
    { const char * tb_v9466 = "        if (!s->d || s->n == 0) { tb_voice_end(v); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9466; }
    { const char * tb_v9467 = "        float tl = (float)v->vol, tr = (float)v->vol, al = 1, ar = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v9467; }
    { const char * tb_v9468 = "        double tdl = 0, tdr = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9468; }
    { const char * tb_v9469 = "        if (v->is3d) tb_voice_3d(v, &tl, &tr, &tdl, &tdr, &al, &ar);\n"; *(const char * *)tb_grow(v_lines) = tb_v9469; }
    { const char * tb_v9470 = "        if (v->stop) { tl = 0; tr = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9470; }
    { const char * tb_v9471 = "        if (v->fresh) { v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr; v->fresh = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9471; }
    { const char * tb_v9472 = "        double step = s->rate / TB_SR * v->pitch * (v->is3d ? v->dop : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v9472; }
    { const char * tb_v9473 = "        float gl = v->gl, gr = v->gr, dgl = (tl - gl) / n, dgr = (tr - gr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9473; }
    { const char * tb_v9474 = "        double dl = v->dl, dr = v->dr, ddl = (tdl - dl) / n, ddr = (tdr - dr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9474; }
    { const char * tb_v9475 = "        int done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9475; }
    { const char * tb_v9476 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9476; }
    { const char * tb_v9477 = "            float l, r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9477; }
    { const char * tb_v9478 = "            if (v->is3d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9478; }
    { const char * tb_v9479 = "                l = tb_smono(s, v->pos - dl * step, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v9479; }
    { const char * tb_v9480 = "                r = tb_smono(s, v->pos - dr * step, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v9480; }
    { const char * tb_v9481 = "                v->lpl += al * (l - v->lpl);\n"; *(const char * *)tb_grow(v_lines) = tb_v9481; }
    { const char * tb_v9482 = "                v->lpr += ar * (r - v->lpr);\n"; *(const char * *)tb_grow(v_lines) = tb_v9482; }
    { const char * tb_v9483 = "                l = v->lpl;\n"; *(const char * *)tb_grow(v_lines) = tb_v9483; }
    { const char * tb_v9484 = "                r = v->lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v9484; }
    { const char * tb_v9485 = "            } else if (s->ch > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9485; }
    { const char * tb_v9486 = "                l = tb_sread(s, v->pos, 0, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v9486; }
    { const char * tb_v9487 = "                r = tb_sread(s, v->pos, 1, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v9487; }
    { const char * tb_v9488 = "            } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v9488; }
    { const char * tb_v9489 = "                l = r = tb_sread(s, v->pos, 0, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v9489; }
    { const char * tb_v9490 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9490; }
    { const char * tb_v9491 = "            out[2 * i] += l * gl;\n"; *(const char * *)tb_grow(v_lines) = tb_v9491; }
    { const char * tb_v9492 = "            out[2 * i + 1] += r * gr;\n"; *(const char * *)tb_grow(v_lines) = tb_v9492; }
    { const char * tb_v9493 = "            gl += dgl; gr += dgr; dl += ddl; dr += ddr;\n"; *(const char * *)tb_grow(v_lines) = tb_v9493; }
    { const char * tb_v9494 = "            v->pos += step;\n"; *(const char * *)tb_grow(v_lines) = tb_v9494; }
    { const char * tb_v9495 = "            if (v->pos >= (double)s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9495; }
    { const char * tb_v9496 = "                if (v->loop) v->pos -= (double)s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9496; }
    { const char * tb_v9497 = "                else { done = 1; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v9497; }
    { const char * tb_v9498 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v9498; }
    { const char * tb_v9499 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v9499; }
    { const char * tb_v9500 = "        v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr;\n"; *(const char * *)tb_grow(v_lines) = tb_v9500; }
    { const char * tb_v9501 = "        if (done || v->stop) tb_voice_end(v);\n"; *(const char * *)tb_grow(v_lines) = tb_v9501; }
    { const char * tb_v9502 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9502; }
    { const char * tb_v9503 = "    float mt = (float)tb_master;\n"; *(const char * *)tb_grow(v_lines) = tb_v9503; }
    { const char * tb_v9504 = "    pthread_mutex_unlock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v9504; }
    { const char * tb_v9505 = "    // общая громкость (плавно) и ограничитель: громко — сразу тише, потом медленно назад\n"; *(const char * *)tb_grow(v_lines) = tb_v9505; }
    { const char * tb_v9506 = "    float dm = (mt - tb_mg) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v9506; }
    { const char * tb_v9507 = "    for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9507; }
    { const char * tb_v9508 = "        tb_mg += dm;\n"; *(const char * *)tb_grow(v_lines) = tb_v9508; }
    { const char * tb_v9509 = "        float l = out[2 * i] * tb_mg, r = out[2 * i + 1] * tb_mg;\n"; *(const char * *)tb_grow(v_lines) = tb_v9509; }
    { const char * tb_v9510 = "        float pk = fabsf(l) > fabsf(r) ? fabsf(l) : fabsf(r);\n"; *(const char * *)tb_grow(v_lines) = tb_v9510; }
    { const char * tb_v9511 = "        if (pk * tb_lim > 0.98f) tb_lim = 0.98f / pk;\n"; *(const char * *)tb_grow(v_lines) = tb_v9511; }
    { const char * tb_v9512 = "        else tb_lim += (1 - tb_lim) * 0.0002f;\n"; *(const char * *)tb_grow(v_lines) = tb_v9512; }
    { const char * tb_v9513 = "        l *= tb_lim; r *= tb_lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v9513; }
    { const char * tb_v9514 = "        out[2 * i] = l > 1 ? 1 : l < -1 ? -1 : l;\n"; *(const char * *)tb_grow(v_lines) = tb_v9514; }
    { const char * tb_v9515 = "        out[2 * i + 1] = r > 1 ? 1 : r < -1 ? -1 : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v9515; }
    { const char * tb_v9516 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9516; }
    { const char * tb_v9517 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v9517; }
    { const char * tb_v9518 = "static long long tb_snd_now_us(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9518; }
