    { const char * tb_v9707 = "    fclose(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v9707; }
    { const char * tb_v9708 = "    if (sz < 12 || memcmp(b, \"RIFF\", 4) != 0 || memcmp(b + 8, \"WAVE\", 4) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9708; }
    { const char * tb_v9709 = "        tb_err = sz >= 4 && memcmp(b, \"OggS\", 4) == 0 ? \"OGG пока не умею: сохрани звук как WAV\" : \"это не WAV-файл\";\n"; *(const char * *)tb_grow(v_lines) = tb_v9709; }
    { const char * tb_v9710 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v9710; }
